INSERT INTO "knowledge"."quy_tac_tong_hop" ("quy_tac_tong_hop_id","rule_version","dieu_kien_json","thu_tu_uu_tien_json","trang_thai") VALUES ('AGG_CAN_HO_V1','CAN_HO_SEED_RULES_20261007','{"COMPLIANT": "all applicable mandatory criteria SATISFIED and no unresolved scope/version/evidence", "INSUFFICIENT": "scope/version unresolved OR no applicable evaluated criterion OR any remaining UNKNOWN without already-proven violation", "NON_COMPLIANT": "any applicable mandatory criterion VIOLATED; or all applicable mandatory criteria MISSING with verified absence", "PARTIAL": "at least one SATISFIED and at least one verified MISSING; no VIOLATED/UNKNOWN", "excluded": "NOT_APPLICABLE excluded with reason; REVIEW_REQUIRED is not a criterion finding"}'::jsonb,'["SCOPE_OR_VERSION_UNRESOLVED=INSUFFICIENT", "PROVEN_VIOLATION=NON_COMPLIANT_WITH_COVERAGE_FLAG", "UNKNOWN=INSUFFICIENT", "ALL_MISSING=NON_COMPLIANT", "MIXED_SATISFIED_MISSING=PARTIAL", "ALL_SATISFIED=COMPLIANT"]'::jsonb,'ENGINE_POLICY');
INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_GYC005','FAM_PARTY_IDENTITY','BVNTD','Phải có tên, địa chỉ, số điện thoại và phương thức liên hệ khác của các bên nếu có.','VBPL001','DKPL0001','2024-07-01',NULL,'NOI_DUNG_BAT_BUOC_CO_DIEU_KIEN','Quan hệ doanh nghiệp/chủ thể kinh doanh với người tiêu dùng theo Điều 3 Luật 19/2023; mục đích tiêu dùng, sinh hoạt, không thương mại phải có căn cứ. Nội dung Điều 23 khoản 3 chỉ bắt buộc trong hợp đồng theo mẫu thực tế. Xác nhận phiên bản và chuyển tiếp tại mốc nghĩa vụ.','Doanh nghiệp','HOP_DONG_PHU_LUC_VA_NGUON_LUAT','Đánh giá các tiêu chí TC_PV_GYC005_01, TC_PV_GYC005_02, TC_PV_GYC005_03. Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Giữ mọi đoạn mâu thuẫn; xét phụ lục/sửa đổi và quy định bắt buộc. Chưa xác định được nội dung có hiệu lực => UNKNOWN cho tiêu chí bị ảnh hưởng, không chọn riêng đoạn thuận lợi.','Evidence phải đúng hợp đồng/phiên bản và khớp trích dẫn. MISSING cần vắng nội dung bắt buộc đã kiểm tra đủ; chứng cứ thực hiện không thể thay bằng cam kết. UNKNOWN được tổng hợp theo rule, không tự coi là PARTIAL.','Xét Điều 80 Luật 19/2023; danh mục QĐ07 đến trước 01/07/2025, TT42 từ 01/07/2025; cần xác minh nghĩa vụ tại thời điểm sử dụng mẫu/nhận tiền.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','NGAY_XAC_LAP_HOAC_SU_DUNG_MAU','MOC_DA_BIEN_SOAN_CAN_DU_KIEN_CA','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true);
INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_GYC062','FAM_FIRST_PAYMENT_CAP','KDBDS','Lần thanh toán đầu tiên không quá 30% giá trị hợp đồng, bao gồm cả tiền đặt cọc.','VBPL005','ART_VBPL005_25','2024-08-01',NULL,'BAT_BUOC','Nhánh thương mại: mua bán căn hộ hình thành trong tương lai, không phải thuê mua, không áp tự động cho NOXH/bán lại cá nhân. Xác minh mốc, giá trị hợp đồng, khoản đặt cọc và chuyển tiếp Điều 83 trước kết luận.','Bên bán','HOP_DONG_PHU_LUC_VA_NGUON_LUAT','Đánh giá các tiêu chí TC_PV_GYC062_01. Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Giữ mọi đoạn mâu thuẫn; xét phụ lục/sửa đổi và quy định bắt buộc. Chưa xác định được nội dung có hiệu lực => UNKNOWN cho tiêu chí bị ảnh hưởng, không chọn riêng đoạn thuận lợi.','Evidence phải đúng hợp đồng/phiên bản và khớp trích dẫn. MISSING cần vắng nội dung bắt buộc đã kiểm tra đủ; chứng cứ thực hiện không thể thay bằng cam kết. UNKNOWN được tổng hợp theo rule, không tự coi là PARTIAL.','Xác định luật hợp đồng tại ngày xác lập, ngày thu/đến hạn và chuyển tiếp Điều 83; không tự hồi tố trần luật mới vào hợp đồng đã xác lập theo luật cũ.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','NGAY_THOA_THUAN_VA_NGAY_THU_TIEN','MOC_DA_BIEN_SOAN_CAN_DU_KIEN_CA','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true);
INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_GYC064','FAM_PRE_HANDOVER_CAP','KDBDS','Trước bàn giao, tổng số tiền thu không quá 70% giá trị hợp đồng; trường hợp bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật định thì không quá 50%.','VBPL005','ART_VBPL005_25','2024-08-01',NULL,'BAT_BUOC','Mua bán nhà ở/công trình hình thành trong tương lai thuộc Điều 25; không dùng checklist thuê mua cho mua bán; xác minh tiến độ, chủ thể bên bán, mốc và chuyển tiếp. Xác nhận hoạt động kinh doanh BĐS và loại tài sản/nghĩa vụ riêng, xét Điều 1 và chuyển tiếp Điều 83; không chỉ dựa vào tiêu đề hợp đồng.','Bên bán','HOP_DONG_PHU_LUC_VA_NGUON_LUAT','Đánh giá các tiêu chí TC_PV_GYC064_01. Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Giữ mọi đoạn mâu thuẫn; xét phụ lục/sửa đổi và quy định bắt buộc. Chưa xác định được nội dung có hiệu lực => UNKNOWN cho tiêu chí bị ảnh hưởng, không chọn riêng đoạn thuận lợi.','Evidence phải đúng hợp đồng/phiên bản và khớp trích dẫn. MISSING cần vắng nội dung bắt buộc đã kiểm tra đủ; chứng cứ thực hiện không thể thay bằng cam kết. UNKNOWN được tổng hợp theo rule, không tự coi là PARTIAL.','Xác định luật hợp đồng tại ngày xác lập, ngày thu/đến hạn và chuyển tiếp Điều 83; không tự hồi tố trần luật mới vào hợp đồng đã xác lập theo luật cũ.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','NGAY_THOA_THUAN_VA_NGAY_THU_TIEN','MOC_DA_BIEN_SOAN_CAN_DU_KIEN_CA','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true);
