INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_GYC104','FAM_MAINTENANCE_2_PERCENT','NHAO','Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng.','VBPL007','ART_VBPL007_152','2024-08-01',NULL,'BAT_BUOC','Cần xác minh phạm vi giao dịch, chủ thể, thời gian và điều khoản chuyển tiếp. Xác nhận loại nhà ở và giao dịch; nội dung giao dịch nhà ở thương mại của doanh nghiệp có chức năng BĐS phải route Luật KDBĐS theo khoản 2 Điều 1.','Bên mua/Bên bán','HOP_DONG_PHU_LUC_VA_NGUON_LUAT','Đánh giá các tiêu chí TC_PV_GYC104_01. Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Giữ mọi đoạn mâu thuẫn; xét phụ lục/sửa đổi và quy định bắt buộc. Chưa xác định được nội dung có hiệu lực => UNKNOWN cho tiêu chí bị ảnh hưởng, không chọn riêng đoạn thuận lợi.','Evidence phải đúng hợp đồng/phiên bản và khớp trích dẫn. MISSING cần vắng nội dung bắt buộc đã kiểm tra đủ; chứng cứ thực hiện không thể thay bằng cam kết. UNKNOWN được tổng hợp theo rule, không tự coi là PARTIAL.','CHUA_XAC_MINH_CHI_TIET_KHONG_TU_AP_LUAT_MOI_HOI_TO','AI_LEGAL_ANNOTATED_PENDING_HUMAN','NGAY_XAC_LAP_HOAC_SU_DUNG_MAU','MOC_DA_BIEN_SOAN_CAN_DU_KIEN_CA','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true);
