INSERT INTO "knowledge"."phien_ban_yeu_cau" ("requirement_version_id","requirement_id","nhom_phien_ban","noi_dung","source_van_ban_id","dieu_khoan_id","hieu_luc_tu","hieu_luc_den","tinh_chat","dieu_kien_ap_dung","chu_the_nghia_vu","pham_vi_bang_chung","tieu_chi_dap_ung","quy_tac_mau_thuan","quy_tac_du_bang_chung","quy_tac_chuyen_tiep","trang_thai_ra_soat","loai_moc_ap_dung","trang_thai_moc","loai_du_lieu","quy_tac_tong_hop_id","trang_thai_runtime","kiem_tra_sua_doi_den","can_xac_minh_scope","can_xac_minh_chuyen_tiep") VALUES ('PV_APT_CERTIFICATE_50D_2024','FAM_APT_CERTIFICATE_50D','CAN_HO_2024','Chủ đầu tư nộp hồ sơ đề nghị cấp Giấy chứng nhận trong 50 ngày kể từ bàn giao, trừ khi người mua tự nguyện tự làm thủ tục.','VBPL005','ART_VBPL005_17','2024-08-01',NULL,'BAT_BUOC_CO_DIEU_KIEN','DEVELOPER Xác nhận hoạt động kinh doanh BĐS và loại tài sản/nghĩa vụ riêng, xét Điều 1 và chuyển tiếp Điều 83; không chỉ dựa vào tiêu đề hợp đồng.','Theo từng điều và tư cách các bên','HOP_DONG_VA_PHU_LUC; CHUNG_TU_THUC_HIEN_KHI_NGHIA_VU_PHAT_SINH','Đánh giá các tiêu chí TC_PV_APT_CERTIFICATE_50D_2024_01. Điều kiện bốn finding nằm tại quy_tac_quyet_dinh; chỉ tổng hợp tiêu chí áp dụng và bắt buộc theo AGG_CAN_HO_V1.','Giữ mọi đoạn mâu thuẫn; xét phụ lục/sửa đổi và quy định bắt buộc. Chưa xác định được nội dung có hiệu lực => UNKNOWN cho tiêu chí bị ảnh hưởng, không chọn riêng đoạn thuận lợi.','Evidence phải đúng hợp đồng/phiên bản và khớp trích dẫn. MISSING cần vắng nội dung bắt buộc đã kiểm tra đủ; chứng cứ thực hiện không thể thay bằng cam kết. UNKNOWN được tổng hợp theo rule, không tự coi là PARTIAL.','Luật 29/2023 Điều 83 và Luật Nhà ở Điều 198; xác nhận chuyển tiếp trước khi chọn bản 2024.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','MOC_PHAT_SINH_VA_DEN_HAN_NGHIA_VU','MOC_DA_BIEN_SOAN_CAN_DU_KIEN_CA','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AGG_CAN_HO_V1','AI_REVIEWED_HUMAN_REVIEW_REQUIRED','2026-10-07',true,true);
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC005_01','PV_GYC005',1,'Tên bên bán và bên mua xác định được.','NOI_DUNG_BAT_BUOC','Chỉ kiểm tra Tên bên bán và bên mua xác định được. Hồ sơ liên quan: tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_CHI_KHI_NOI_DUNG_BAT_BUOC_VA_DA_KIEM_TRA_TOAN_BO','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','DKPL0001','19/2023/QH15; Điều 23 khoản 3 điểm a','https://datafiles.chinhphu.vn/cpp/files/vbpq/2023/7/luat19_2023.pdf','Quan hệ doanh nghiệp/chủ thể kinh doanh với người tiêu dùng theo Điều 3 Luật 19/2023; mục đích tiêu dùng, sinh hoạt, không thương mại phải có căn cứ. Nội dung Điều 23 khoản 3 chỉ bắt buộc trong hợp đồng theo mẫu thực tế. Xác nhận phiên bản và chuyển tiếp tại mốc nghĩa vụ.','Chỉ kiểm tra nội dung bắt buộc của hợp đồng theo mẫu; quan hệ doanh nghiệp phục vụ thương mại không tự thuộc phạm vi. Thành phần liên hệ khác chỉ khi có; cấu thành giá khi luật yêu cầu. Luật cho phép thỏa thuận/mặc định và điều kiện phát sinh của đúng tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07','AI_DOI_CHIEU_NGUON_CHINH_THUC_CHUA_DUYET',true,'NOI_DUNG_HOP_DONG_THEO_MAU','{"MISSING": "ADD_MANDATORY_CONTENT", "SATISFIED": null, "UNKNOWN": "REQUEST_EVIDENCE", "VIOLATED": "AMEND_OR_CORRECT_PROVEN_BREACH", "scope_and_version_required": true, "source_required": true}'::jsonb);
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC005_02','PV_GYC005',2,'Địa chỉ của các bên xác định được.','NOI_DUNG_BAT_BUOC','Chỉ kiểm tra Địa chỉ của các bên xác định được. Hồ sơ liên quan: địa chỉ bên bán, địa chỉ bên mua, địa chỉ nhận thông báo khi khác. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_CHI_KHI_NOI_DUNG_BAT_BUOC_VA_DA_KIEM_TRA_TOAN_BO','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','DKPL0001','19/2023/QH15; Điều 23 khoản 3 điểm a','https://datafiles.chinhphu.vn/cpp/files/vbpq/2023/7/luat19_2023.pdf','Quan hệ doanh nghiệp/chủ thể kinh doanh với người tiêu dùng theo Điều 3 Luật 19/2023; mục đích tiêu dùng, sinh hoạt, không thương mại phải có căn cứ. Nội dung Điều 23 khoản 3 chỉ bắt buộc trong hợp đồng theo mẫu thực tế. Xác nhận phiên bản và chuyển tiếp tại mốc nghĩa vụ.','Chỉ kiểm tra nội dung bắt buộc của hợp đồng theo mẫu; quan hệ doanh nghiệp phục vụ thương mại không tự thuộc phạm vi. Thành phần liên hệ khác chỉ khi có; cấu thành giá khi luật yêu cầu. Luật cho phép thỏa thuận/mặc định và điều kiện phát sinh của đúng tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07','AI_DOI_CHIEU_NGUON_CHINH_THUC_CHUA_DUYET',true,'NOI_DUNG_HOP_DONG_THEO_MAU','{"MISSING": "ADD_MANDATORY_CONTENT", "SATISFIED": null, "UNKNOWN": "REQUEST_EVIDENCE", "VIOLATED": "AMEND_OR_CORRECT_PROVEN_BREACH", "scope_and_version_required": true, "source_required": true}'::jsonb);
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC005_03','PV_GYC005',3,'Có số điện thoại và phương thức liên hệ khác nếu có.','NOI_DUNG_BAT_BUOC','Chỉ kiểm tra Có số điện thoại và phương thức liên hệ khác nếu có. Hồ sơ liên quan: số điện thoại các bên khi thuộc nội dung bắt buộc, phương thức liên hệ khác nếu có. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_CHI_KHI_NOI_DUNG_BAT_BUOC_VA_DA_KIEM_TRA_TOAN_BO','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','DKPL0001','19/2023/QH15; Điều 23 khoản 3 điểm a','https://datafiles.chinhphu.vn/cpp/files/vbpq/2023/7/luat19_2023.pdf','Quan hệ doanh nghiệp/chủ thể kinh doanh với người tiêu dùng theo Điều 3 Luật 19/2023; mục đích tiêu dùng, sinh hoạt, không thương mại phải có căn cứ. Nội dung Điều 23 khoản 3 chỉ bắt buộc trong hợp đồng theo mẫu thực tế. Xác nhận phiên bản và chuyển tiếp tại mốc nghĩa vụ.','Chỉ kiểm tra nội dung bắt buộc của hợp đồng theo mẫu; quan hệ doanh nghiệp phục vụ thương mại không tự thuộc phạm vi. Thành phần liên hệ khác chỉ khi có; cấu thành giá khi luật yêu cầu. Luật cho phép thỏa thuận/mặc định và điều kiện phát sinh của đúng tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07','AI_DOI_CHIEU_NGUON_CHINH_THUC_CHUA_DUYET',true,'NOI_DUNG_HOP_DONG_THEO_MAU','{"MISSING": "ADD_MANDATORY_CONTENT", "SATISFIED": null, "UNKNOWN": "REQUEST_EVIDENCE", "VIOLATED": "AMEND_OR_CORRECT_PROVEN_BREACH", "scope_and_version_required": true, "source_required": true}'::jsonb);
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC062_01','PV_GYC062',1,'Lần thanh toán đầu tiên không quá 30% giá trị hợp đồng, bao gồm cả tiền đặt cọc.','PERFORMANCE_WITH_DOCUMENTS','Chỉ kiểm tra Lần thanh toán đầu tiên không quá 30% giá trị hợp đồng, bao gồm cả tiền đặt cọc. Hồ sơ liên quan: giá trị hợp đồng làm mẫu số, đặt cọc, lịch và khoản đã thu, tình trạng bàn giao/cấp giấy, tư cách vốn nước ngoài khi áp dụng. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL005_25','29/2023/QH15; Điều 25 khoản 1','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','Nhánh thương mại: mua bán căn hộ hình thành trong tương lai, không phải thuê mua, không áp tự động cho NOXH/bán lại cá nhân. Xác minh mốc, giá trị hợp đồng, khoản đặt cọc và chuyển tiếp Điều 83 trước kết luận.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Luật cho phép thỏa thuận/mặc định và điều kiện phát sinh của đúng tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07','SOURCE_EXTRACTED_PENDING_HUMAN',false,'CONDITIONAL_OR_EXTERNAL_FACTS','{"MISSING": null, "SATISFIED": null, "UNKNOWN": "REQUEST_EVIDENCE", "VIOLATED": "AMEND_OR_CORRECT_PROVEN_BREACH", "scope_and_version_required": true, "source_required": true}'::jsonb);
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC064_01','PV_GYC064',1,'Trước bàn giao, tổng số tiền thu không quá 70% giá trị hợp đồng; trường hợp bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật định thì không quá 50%.','PERFORMANCE_WITH_DOCUMENTS','Chỉ kiểm tra Trước bàn giao, tổng số tiền thu không quá 70% giá trị hợp đồng; trường hợp bên bán là tổ chức kinh tế có vốn đầu tư nước ngoài thuộc diện luật định thì không quá 50%. Hồ sơ liên quan: giá trị hợp đồng làm mẫu số, đặt cọc, lịch và khoản đã thu, tình trạng bàn giao/cấp giấy, tư cách vốn nước ngoài khi áp dụng. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL005_25','29/2023/QH15; Điều 25 khoản 1','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','Mua bán nhà ở/công trình hình thành trong tương lai thuộc Điều 25; không dùng checklist thuê mua cho mua bán; xác minh tiến độ, chủ thể bên bán, mốc và chuyển tiếp. Xác nhận hoạt động kinh doanh BĐS và loại tài sản/nghĩa vụ riêng, xét Điều 1 và chuyển tiếp Điều 83; không chỉ dựa vào tiêu đề hợp đồng.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Luật cho phép thỏa thuận/mặc định và điều kiện phát sinh của đúng tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07','SOURCE_EXTRACTED_PENDING_HUMAN',false,'CONDITIONAL_OR_EXTERNAL_FACTS','{"MISSING": null, "SATISFIED": null, "UNKNOWN": "REQUEST_EVIDENCE", "VIOLATED": "AMEND_OR_CORRECT_PROVEN_BREACH", "scope_and_version_required": true, "source_required": true}'::jsonb);
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC065_01','PV_GYC065',1,'Nếu người mua chưa được cấp Giấy chứng nhận thì bên bán không được thu quá 95% giá trị hợp đồng; phần còn lại thanh toán khi Giấy chứng nhận được cấp.','PERFORMANCE_WITH_DOCUMENTS','Chỉ kiểm tra Nếu người mua chưa được cấp Giấy chứng nhận thì bên bán không được thu quá 95% giá trị hợp đồng; phần còn lại thanh toán khi Giấy chứng nhận được cấp. Hồ sơ liên quan: giá trị hợp đồng làm mẫu số, đặt cọc, lịch và khoản đã thu, tình trạng bàn giao/cấp giấy, tư cách vốn nước ngoài khi áp dụng. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','NO_MISSING_FOR_CONDITIONAL_PERFORMANCE_FORMAT_OR_CONSISTENCY','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL005_25','29/2023/QH15; Điều 25 khoản 3','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','Mua bán nhà ở/công trình hình thành trong tương lai thuộc Điều 25; không dùng checklist thuê mua cho mua bán; xác minh tiến độ, chủ thể bên bán, mốc và chuyển tiếp. Xác nhận hoạt động kinh doanh BĐS và loại tài sản/nghĩa vụ riêng, xét Điều 1 và chuyển tiếp Điều 83; không chỉ dựa vào tiêu đề hợp đồng.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Luật cho phép thỏa thuận/mặc định và điều kiện phát sinh của đúng tiêu chí phải được xét; dữ kiện chưa rõ là UNKNOWN.','2026-10-07','SOURCE_EXTRACTED_PENDING_HUMAN',false,'CONDITIONAL_OR_EXTERNAL_FACTS','{"MISSING": null, "SATISFIED": null, "UNKNOWN": "REQUEST_EVIDENCE", "VIOLATED": "AMEND_OR_CORRECT_PROVEN_BREACH", "scope_and_version_required": true, "source_required": true}'::jsonb);
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC104_01','PV_GYC104',1,'Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng.','CONTRACT_CONTENT','Chỉ kiểm tra Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng. Hồ sơ liên quan: mức 2% khi áp dụng, giá trị căn hộ/phần diện tích làm căn cứ, tách khoản bảo trì khỏi giá bán, trách nhiệm từng chủ sở hữu, tài khoản và chứng từ. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_ONLY_AFTER_FULL_DOCUMENT_AND_ANNEX_REVIEW','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL007_152','27/2023/QH15; Điều 152 khoản 1','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat27_tiep.pdf','Cần xác minh phạm vi giao dịch, chủ thể, thời gian và điều khoản chuyển tiếp. Xác nhận loại nhà ở và giao dịch; nội dung giao dịch nhà ở thương mại của doanh nghiệp có chức năng BĐS phải route Luật KDBĐS theo khoản 2 Điều 1.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Hợp đồng trước 01/07/2006 hoặc giai đoạn 01/07/2006 đến trước luật mới phải đối chiếu khoản 3,4 Điều 152, không mặc định toàn bộ đều 2% người mua đóng.','2026-10-07','SOURCE_EXTRACTED_PENDING_HUMAN',true,'CONTRACT_TEXT','{"MISSING": "ADD_MANDATORY_CONTENT", "SATISFIED": null, "UNKNOWN": "REQUEST_EVIDENCE", "VIOLATED": "AMEND_OR_CORRECT_PROVEN_BREACH", "scope_and_version_required": true, "source_required": true}'::jsonb);
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_GYC154_01','PV_GYC154',1,'Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng.','CONTRACT_CONTENT','Chỉ kiểm tra Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng. Hồ sơ liên quan: đối tượng/ phạm vi bảo hành, thời hạn, mốc hoàn thành và nghiệm thu, đầu mối và cách thông báo, bảo hành thiết bị theo nhà sản xuất. Phụ lục dẫn chiếu chưa nhận hoặc text OCR không đủ thì chưa xác nhận vắng nội dung.','MISSING_ONLY_AFTER_FULL_DOCUMENT_AND_ANNEX_REVIEW','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL007_129','27/2023/QH15; Điều 129 khoản 2 điểm a','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat27_tiep.pdf','Cần xác minh phạm vi giao dịch, chủ thể, thời gian và điều khoản chuyển tiếp. Xác nhận loại nhà ở và giao dịch; nội dung giao dịch nhà ở thương mại của doanh nghiệp có chức năng BĐS phải route Luật KDBĐS theo khoản 2 Điều 1.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Thiết bị có thời hạn nhà sản xuất; bán lại không tự khởi động lại bảo hành nhà chung cư 60 tháng.','2026-10-07','SOURCE_EXTRACTED_PENDING_HUMAN',true,'CONTRACT_TEXT','{"MISSING": "ADD_MANDATORY_CONTENT", "SATISFIED": null, "UNKNOWN": "REQUEST_EVIDENCE", "VIOLATED": "AMEND_OR_CORRECT_PROVEN_BREACH", "scope_and_version_required": true, "source_required": true}'::jsonb);
INSERT INTO "knowledge"."tieu_chi_danh_gia" ("tieu_chi_id","requirement_version_id","thu_tu","noi_dung","loai_kiem_tra","bang_chung_can_thiet","missing_policy","trang_thai","human_verified","bat_buoc","loai_du_lieu","source_dieu_khoan_id","can_cu_cu_the","url_can_cu","pham_vi_ap_dung_chi_tiet","ngoai_le_can_xet","ngay_ra_soat","trang_thai_nguon","noi_dung_bat_buoc_trong_hd","pham_vi_kiem_tra","can_khac_phuc_json") VALUES ('TC_PV_APT_CERTIFICATE_50D_2024_01','PV_APT_CERTIFICATE_50D_2024',1,'Chủ đầu tư nộp hồ sơ đề nghị cấp Giấy chứng nhận trong 50 ngày kể từ bàn giao, trừ khi người mua tự nguyện tự làm thủ tục.','PERFORMANCE_WITH_DOCUMENTS','Chỉ kiểm tra Chủ đầu tư nộp hồ sơ đề nghị cấp Giấy chứng nhận trong 50 ngày kể từ bàn giao, trừ khi người mua tự nguyện tự làm thủ tục. Hồ sơ liên quan: chủ thể thực hiện thủ tục, ngày bàn giao hoặc sự kiện gốc, thời điểm nộp hồ sơ, nguyện vọng tự làm của người mua nếu có, biên nhận hồ sơ. Cần chứng từ thực hiện; cam kết trong hợp đồng chưa chứng minh hoàn thành.','UNKNOWN_IF_EXTERNAL_PROOF_OR_INCOMPLETE_COVERAGE','AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,true,'AI_LEGAL_ANNOTATED_PENDING_HUMAN','ART_VBPL005_17','29/2023/QH15; Điều 17 khoản 3','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','DEVELOPER Xác nhận hoạt động kinh doanh BĐS và loại tài sản/nghĩa vụ riêng, xét Điều 1 và chuyển tiếp Điều 83; không chỉ dựa vào tiêu đề hợp đồng.','Xác nhận scope, chuyển tiếp, subtype; mẫu thương mại không áp máy móc cho NOXH/căn hộ bán lại. Người mua tự nguyện làm hồ sơ cấp giấy: xét ngoại lệ nghĩa vụ chủ đầu tư nộp hồ sơ trong 50 ngày.','2026-10-07','SOURCE_EXTRACTED_PENDING_HUMAN',false,'PERFORMANCE','{"MISSING": null, "SATISFIED": null, "UNKNOWN": "REQUEST_EVIDENCE", "VIOLATED": "AMEND_OR_CORRECT_PROVEN_BREACH", "scope_and_version_required": true, "source_required": true}'::jsonb);
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_01_UNKNOWN','TC_PV_GYC005_01','UNKNOWN', E'{"criterion_target_only": true, "enabled": true, "gate": {"any_unresolved_fact": true}, "human_approval_required_for_final": true, "numeric_rule": null, "predicate": "UNKNOWN n\\u1ebfu ngu\\u1ed3n/phi\\u00ean b\\u1ea3n/scope ho\\u1eb7c d\\u1eef ki\\u1ec7n c\\u1ea7n cho ch\\u00ednh ti\\u00eau ch\\u00ed ch\\u01b0a \\u0111\\u01b0\\u1ee3c x\\u00e1c nh\\u1eadn, t\\u00e0i li\\u1ec7u li\\u00ean quan ch\\u01b0a \\u0111\\u1ee7, OCR kh\\u00f4ng \\u0111\\u1ecdc \\u0111\\u01b0\\u1ee3c, m\\u00e2u thu\\u1eabn ch\\u01b0a x\\u1eed l\\u00fd, tr\\u01b0\\u1eddng c\\u1ee7a m\\u1eabu ch\\u01b0a \\u0111\\u01b0\\u1ee3c \\u0111i\\u1ec1n ho\\u1eb7c thi\\u1ebfu ch\\u1ee9ng t\\u1eeb th\\u1ef1c hi\\u1ec7n. C\\u1ea7n l\\u00e0m r\\u00f5: t\\u00ean \\u0111\\u1ea7y \\u0111\\u1ee7 b\\u00ean b\\u00e1n, t\\u00ean \\u0111\\u1ea7y \\u0111\\u1ee7 b\\u00ean mua, t\\u01b0 c\\u00e1ch ng\\u01b0\\u1eddi \\u0111\\u1ea1i di\\u1ec7n n\\u1ebfu c\\u00f3.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'UNKNOWN nếu nguồn/phiên bản/scope hoặc dữ kiện cần cho chính tiêu chí chưa được xác nhận, tài liệu liên quan chưa đủ, OCR không đọc được, mâu thuẫn chưa xử lý, trường của mẫu chưa được điền hoặc thiếu chứng từ thực hiện. Cần làm rõ: tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có.',100,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_01_VIOLATED','TC_PV_GYC005_01','VIOLATED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": null, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn VIOLATED khi b\\u1eb1ng ch\\u1ee9ng ch\\u1ee9ng minh tr\\u00e1i m\\u1ec7nh \\u0111\\u1ec1: T\\u00ean b\\u00ean b\\u00e1n v\\u00e0 b\\u00ean mua x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c. T\\u00ean/ch\\u1ee7 th\\u1ec3 ho\\u1eb7c ng\\u01b0\\u1eddi k\\u00fd trong h\\u1ee3p \\u0111\\u1ed3ng tr\\u00e1i h\\u1ed3 s\\u01a1 \\u0111\\u1ecbnh danh/\\u1ee7y quy\\u1ec1n h\\u1ee3p l\\u1ec7 \\u0111\\u00e3 \\u0111\\u1ed1i chi\\u1ebfu; kh\\u00f4ng suy vi ph\\u1ea1m ch\\u1ec9 t\\u1eeb t\\u00ean vi\\u1ebft t\\u1eaft ho\\u1eb7c ch\\u1ed7 tr\\u1ed1ng c\\u1ee7a m\\u1eabu.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Tên bên bán và bên mua xác định được. Tên/chủ thể hoặc người ký trong hợp đồng trái hồ sơ định danh/ủy quyền hợp lệ đã đối chiếu; không suy vi phạm chỉ từ tên viết tắt hoặc chỗ trống của mẫu.',80,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_01_MISSING','TC_PV_GYC005_01','MISSING', E'{"criterion_target_only": true, "enabled": true, "gate": {"absence_verified": true, "coverage_complete": true, "criterion_content_absent": true, "evidence_validated": true, "exceptions_resolved": true, "mandatory_contract_content": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "template_field_unfilled": false, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": null, "predicate": "\\u0110\\u00e3 x\\u00e1c nh\\u1eadn n\\u1ed9i dung b\\u1eaft bu\\u1ed9c, scope/phi\\u00ean b\\u1ea3n/ngo\\u1ea1i l\\u1ec7 v\\u00e0 \\u0111\\u00e3 \\u0111\\u1ecdc \\u0111\\u1ee7 h\\u1ee3p \\u0111\\u1ed3ng/ph\\u1ee5 l\\u1ee5c nh\\u01b0ng kh\\u00f4ng c\\u00f3 n\\u1ed9i dung \\u0111\\u00e1p \\u1ee9ng m\\u1ec7nh \\u0111\\u1ec1: T\\u00ean b\\u00ean b\\u00e1n v\\u00e0 b\\u00ean mua x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c. Kh\\u00f4ng d\\u00f9ng top-K tr\\u1ed1ng l\\u00e0m ch\\u1ee9ng minh v\\u1eafng to\\u00e0n v\\u0103n; ch\\u1ed7 tr\\u1ed1ng d\\u1ef1 th\\u1ea3o ch\\u01b0a giao k\\u1ebft \\u0111\\u01b0\\u1ee3c x\\u1eed l\\u00fd UNKNOWN/c\\u1ea7n ho\\u00e0n thi\\u1ec7n.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Đã xác nhận nội dung bắt buộc, scope/phiên bản/ngoại lệ và đã đọc đủ hợp đồng/phụ lục nhưng không có nội dung đáp ứng mệnh đề: Tên bên bán và bên mua xác định được. Không dùng top-K trống làm chứng minh vắng toàn văn; chỗ trống dự thảo chưa giao kết được xử lý UNKNOWN/cần hoàn thiện.',70,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_01_SATISFIED','TC_PV_GYC005_01','SATISFIED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": null, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn SATISFIED cho m\\u1ec7nh \\u0111\\u1ec1: T\\u00ean b\\u00ean b\\u00e1n v\\u00e0 b\\u00ean mua x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c. T\\u00ean hai b\\u00ean v\\u00e0 ng\\u01b0\\u1eddi k\\u00fd x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c; t\\u1ed5 ch\\u1ee9c/c\\u00e1 nh\\u00e2n \\u0111\\u01b0\\u1ee3c ph\\u00e2n bi\\u1ec7t \\u0111\\u00fang. T\\u00ean trong v\\u0103n b\\u1ea3n ch\\u01b0a ch\\u1ee9ng minh t\\u01b0 c\\u00e1ch ho\\u1eb7c th\\u1ea9m quy\\u1ec1n ngo\\u00e0i \\u0111\\u1eddi. Kh\\u00f4ng y\\u00eau c\\u1ea7u to\\u00e0n b\\u1ed9 y\\u1ebfu t\\u1ed1 c\\u1ee7a nh\\u00f3m n\\u1ebfu ch\\u00fang n\\u1eb1m ngo\\u00e0i m\\u1ec7nh \\u0111\\u1ec1 n\\u00e0y.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận SATISFIED cho mệnh đề: Tên bên bán và bên mua xác định được. Tên hai bên và người ký xác định được; tổ chức/cá nhân được phân biệt đúng. Tên trong văn bản chưa chứng minh tư cách hoặc thẩm quyền ngoài đời. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_02_UNKNOWN','TC_PV_GYC005_02','UNKNOWN', E'{"criterion_target_only": true, "enabled": true, "gate": {"any_unresolved_fact": true}, "human_approval_required_for_final": true, "numeric_rule": null, "predicate": "UNKNOWN n\\u1ebfu ngu\\u1ed3n/phi\\u00ean b\\u1ea3n/scope ho\\u1eb7c d\\u1eef ki\\u1ec7n c\\u1ea7n cho ch\\u00ednh ti\\u00eau ch\\u00ed ch\\u01b0a \\u0111\\u01b0\\u1ee3c x\\u00e1c nh\\u1eadn, t\\u00e0i li\\u1ec7u li\\u00ean quan ch\\u01b0a \\u0111\\u1ee7, OCR kh\\u00f4ng \\u0111\\u1ecdc \\u0111\\u01b0\\u1ee3c, m\\u00e2u thu\\u1eabn ch\\u01b0a x\\u1eed l\\u00fd, tr\\u01b0\\u1eddng c\\u1ee7a m\\u1eabu ch\\u01b0a \\u0111\\u01b0\\u1ee3c \\u0111i\\u1ec1n ho\\u1eb7c thi\\u1ebfu ch\\u1ee9ng t\\u1eeb th\\u1ef1c hi\\u1ec7n. C\\u1ea7n l\\u00e0m r\\u00f5: \\u0111\\u1ecba ch\\u1ec9 b\\u00ean b\\u00e1n, \\u0111\\u1ecba ch\\u1ec9 b\\u00ean mua, \\u0111\\u1ecba ch\\u1ec9 nh\\u1eadn th\\u00f4ng b\\u00e1o khi kh\\u00e1c.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'UNKNOWN nếu nguồn/phiên bản/scope hoặc dữ kiện cần cho chính tiêu chí chưa được xác nhận, tài liệu liên quan chưa đủ, OCR không đọc được, mâu thuẫn chưa xử lý, trường của mẫu chưa được điền hoặc thiếu chứng từ thực hiện. Cần làm rõ: địa chỉ bên bán, địa chỉ bên mua, địa chỉ nhận thông báo khi khác.',100,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_02_VIOLATED','TC_PV_GYC005_02','VIOLATED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": null, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn VIOLATED khi b\\u1eb1ng ch\\u1ee9ng ch\\u1ee9ng minh tr\\u00e1i m\\u1ec7nh \\u0111\\u1ec1: \\u0110\\u1ecba ch\\u1ec9 c\\u1ee7a c\\u00e1c b\\u00ean x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c. \\u0110\\u1ecba ch\\u1ec9 tr\\u00e1i h\\u1ed3 s\\u01a1 \\u0111\\u00e3 x\\u00e1c minh ho\\u1eb7c c\\u01a1 ch\\u1ebf th\\u00f4ng b\\u00e1o lo\\u1ea1i b\\u1ecf quy\\u1ec1n nh\\u1eadn th\\u00f4ng b\\u00e1o c\\u1ee7a m\\u1ed9t b\\u00ean.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Địa chỉ của các bên xác định được. Địa chỉ trái hồ sơ đã xác minh hoặc cơ chế thông báo loại bỏ quyền nhận thông báo của một bên.',80,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
