INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_02_SATISFIED','TC_PV_GYC005_02','SATISFIED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": null, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn SATISFIED cho m\\u1ec7nh \\u0111\\u1ec1: \\u0110\\u1ecba ch\\u1ec9 c\\u1ee7a c\\u00e1c b\\u00ean x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c. \\u0110\\u1ecba ch\\u1ec9 c\\u1ee7a c\\u1ea3 hai b\\u00ean \\u0111\\u1ee7 x\\u00e1c \\u0111\\u1ecbnh, c\\u00f3 th\\u1ec3 d\\u1eabn chi\\u1ebfu ph\\u1ee5 l\\u1ee5c h\\u1ee3p l\\u1ec7; \\u0111\\u1ecba ch\\u1ec9 ph\\u00e1p l\\u00fd v\\u00e0 nh\\u1eadn th\\u00f4ng b\\u00e1o \\u0111\\u01b0\\u1ee3c ph\\u00e2n bi\\u1ec7t khi kh\\u00e1c nhau. Kh\\u00f4ng y\\u00eau c\\u1ea7u to\\u00e0n b\\u1ed9 y\\u1ebfu t\\u1ed1 c\\u1ee7a nh\\u00f3m n\\u1ebfu ch\\u00fang n\\u1eb1m ngo\\u00e0i m\\u1ec7nh \\u0111\\u1ec1 n\\u00e0y.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận SATISFIED cho mệnh đề: Địa chỉ của các bên xác định được. Địa chỉ của cả hai bên đủ xác định, có thể dẫn chiếu phụ lục hợp lệ; địa chỉ pháp lý và nhận thông báo được phân biệt khi khác nhau. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC005_03_UNKNOWN','TC_PV_GYC005_03','UNKNOWN', E'{"criterion_target_only": true, "enabled": true, "gate": {"any_unresolved_fact": true}, "human_approval_required_for_final": true, "numeric_rule": null, "predicate": "UNKNOWN n\\u1ebfu ngu\\u1ed3n/phi\\u00ean b\\u1ea3n/scope ho\\u1eb7c d\\u1eef ki\\u1ec7n c\\u1ea7n cho ch\\u00ednh ti\\u00eau ch\\u00ed ch\\u01b0a \\u0111\\u01b0\\u1ee3c x\\u00e1c nh\\u1eadn, t\\u00e0i li\\u1ec7u li\\u00ean quan ch\\u01b0a \\u0111\\u1ee7, OCR kh\\u00f4ng \\u0111\\u1ecdc \\u0111\\u01b0\\u1ee3c, m\\u00e2u thu\\u1eabn ch\\u01b0a x\\u1eed l\\u00fd, tr\\u01b0\\u1eddng c\\u1ee7a m\\u1eabu ch\\u01b0a \\u0111\\u01b0\\u1ee3c \\u0111i\\u1ec1n ho\\u1eb7c thi\\u1ebfu ch\\u1ee9ng t\\u1eeb th\\u1ef1c hi\\u1ec7n. C\\u1ea7n l\\u00e0m r\\u00f5: s\\u1ed1 \\u0111i\\u1ec7n tho\\u1ea1i c\\u00e1c b\\u00ean khi thu\\u1ed9c n\\u1ed9i dung b\\u1eaft bu\\u1ed9c, ph\\u01b0\\u01a1ng th\\u1ee9c li\\u00ean h\\u1ec7 kh\\u00e1c n\\u1ebfu c\\u00f3.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'UNKNOWN nếu nguồn/phiên bản/scope hoặc dữ kiện cần cho chính tiêu chí chưa được xác nhận, tài liệu liên quan chưa đủ, OCR không đọc được, mâu thuẫn chưa xử lý, trường của mẫu chưa được điền hoặc thiếu chứng từ thực hiện. Cần làm rõ: số điện thoại các bên khi thuộc nội dung bắt buộc, phương thức liên hệ khác nếu có.',100,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
