INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC104_01_VIOLATED','TC_PV_GYC104_01','VIOLATED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": {"maintenance_ratio": 0.02, "scope": "DEVELOPER_SALE_MULTIPLE_OWNERS_NEW_RULES", "separate_from_sale_price": true}, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn VIOLATED khi b\\u1eb1ng ch\\u1ee9ng ch\\u1ee9ng minh tr\\u00e1i m\\u1ec7nh \\u0111\\u1ec1: Ng\\u01b0\\u1eddi mua ph\\u1ea3i \\u0111\\u00f3ng kinh ph\\u00ed b\\u1ea3o tr\\u00ec b\\u1eb1ng 2% gi\\u00e1 tr\\u1ecb c\\u0103n h\\u1ed9/ph\\u1ea7n di\\u1ec7n t\\u00edch b\\u00e1n; kho\\u1ea3n n\\u00e0y t\\u00ednh ri\\u00eang v\\u1edbi ti\\u1ec1n b\\u00e1n v\\u00e0 ph\\u1ea3i quy \\u0111\\u1ecbnh r\\u00f5 trong h\\u1ee3p \\u0111\\u1ed3ng. G\\u1ed9p kho\\u1ea3n 2% v\\u00e0o gi\\u00e1 b\\u00e1n theo c\\u00e1ch kh\\u00f4ng th\\u1ec3 t\\u00e1ch, t\\u00ednh ho\\u1eb7c ph\\u00e2n b\\u1ed5 sai c\\u0103n c\\u1ee9/ch\\u1ee7 th\\u1ec3 ho\\u1eb7c c\\u00f3 ch\\u1ee9ng c\\u1ee9 s\\u1eed d\\u1ee5ng sai m\\u1ee5c \\u0111\\u00edch.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng. Gộp khoản 2% vào giá bán theo cách không thể tách, tính hoặc phân bổ sai căn cứ/chủ thể hoặc có chứng cứ sử dụng sai mục đích.',80,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC104_01_MISSING','TC_PV_GYC104_01','MISSING', E'{"criterion_target_only": true, "enabled": true, "gate": {"absence_verified": true, "coverage_complete": true, "criterion_content_absent": true, "evidence_validated": true, "exceptions_resolved": true, "mandatory_contract_content": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "template_field_unfilled": false, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": {"maintenance_ratio": 0.02, "scope": "DEVELOPER_SALE_MULTIPLE_OWNERS_NEW_RULES", "separate_from_sale_price": true}, "predicate": "\\u0110\\u00e3 x\\u00e1c nh\\u1eadn n\\u1ed9i dung b\\u1eaft bu\\u1ed9c, scope/phi\\u00ean b\\u1ea3n/ngo\\u1ea1i l\\u1ec7 v\\u00e0 \\u0111\\u00e3 \\u0111\\u1ecdc \\u0111\\u1ee7 h\\u1ee3p \\u0111\\u1ed3ng/ph\\u1ee5 l\\u1ee5c nh\\u01b0ng kh\\u00f4ng c\\u00f3 n\\u1ed9i dung \\u0111\\u00e1p \\u1ee9ng m\\u1ec7nh \\u0111\\u1ec1: Ng\\u01b0\\u1eddi mua ph\\u1ea3i \\u0111\\u00f3ng kinh ph\\u00ed b\\u1ea3o tr\\u00ec b\\u1eb1ng 2% gi\\u00e1 tr\\u1ecb c\\u0103n h\\u1ed9/ph\\u1ea7n di\\u1ec7n t\\u00edch b\\u00e1n; kho\\u1ea3n n\\u00e0y t\\u00ednh ri\\u00eang v\\u1edbi ti\\u1ec1n b\\u00e1n v\\u00e0 ph\\u1ea3i quy \\u0111\\u1ecbnh r\\u00f5 trong h\\u1ee3p \\u0111\\u1ed3ng. Kh\\u00f4ng d\\u00f9ng top-K tr\\u1ed1ng l\\u00e0m ch\\u1ee9ng minh v\\u1eafng to\\u00e0n v\\u0103n; ch\\u1ed7 tr\\u1ed1ng d\\u1ef1 th\\u1ea3o ch\\u01b0a giao k\\u1ebft \\u0111\\u01b0\\u1ee3c x\\u1eed l\\u00fd UNKNOWN/c\\u1ea7n ho\\u00e0n thi\\u1ec7n.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Đã xác nhận nội dung bắt buộc, scope/phiên bản/ngoại lệ và đã đọc đủ hợp đồng/phụ lục nhưng không có nội dung đáp ứng mệnh đề: Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng. Không dùng top-K trống làm chứng minh vắng toàn văn; chỗ trống dự thảo chưa giao kết được xử lý UNKNOWN/cần hoàn thiện.',70,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC104_01_SATISFIED','TC_PV_GYC104_01','SATISFIED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": {"maintenance_ratio": 0.02, "scope": "DEVELOPER_SALE_MULTIPLE_OWNERS_NEW_RULES", "separate_from_sale_price": true}, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn SATISFIED cho m\\u1ec7nh \\u0111\\u1ec1: Ng\\u01b0\\u1eddi mua ph\\u1ea3i \\u0111\\u00f3ng kinh ph\\u00ed b\\u1ea3o tr\\u00ec b\\u1eb1ng 2% gi\\u00e1 tr\\u1ecb c\\u0103n h\\u1ed9/ph\\u1ea7n di\\u1ec7n t\\u00edch b\\u00e1n; kho\\u1ea3n n\\u00e0y t\\u00ednh ri\\u00eang v\\u1edbi ti\\u1ec1n b\\u00e1n v\\u00e0 ph\\u1ea3i quy \\u0111\\u1ecbnh r\\u00f5 trong h\\u1ee3p \\u0111\\u1ed3ng. \\u0110\\u00fang scope \\u0110i\\u1ec1u 152: ng\\u01b0\\u1eddi mua/ng\\u01b0\\u1eddi thu\\u00ea mua v\\u00e0 ch\\u1ee7 \\u0111\\u1ea7u t\\u01b0 \\u0111\\u1ed1i v\\u1edbi ph\\u1ea7n gi\\u1eef l\\u1ea1i \\u0111\\u00f3ng kho\\u1ea3n 2% t\\u01b0\\u01a1ng \\u1ee9ng; kho\\u1ea3n n\\u00e0y t\\u00e1ch kh\\u1ecfi gi\\u00e1 b\\u00e1n, h\\u1ed3 s\\u01a1 qu\\u1ea3n l\\u00fd/ph\\u00e2n b\\u1ed5 ph\\u00f9 h\\u1ee3p khi \\u0111\\u00e1nh gi\\u00e1 th\\u1ef1c t\\u1ebf. Kh\\u00f4ng y\\u00eau c\\u1ea7u to\\u00e0n b\\u1ed9 y\\u1ebfu t\\u1ed1 c\\u1ee7a nh\\u00f3m n\\u1ebfu ch\\u00fang n\\u1eb1m ngo\\u00e0i m\\u1ec7nh \\u0111\\u1ec1 n\\u00e0y.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận SATISFIED cho mệnh đề: Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng. Đúng scope Điều 152: người mua/người thuê mua và chủ đầu tư đối với phần giữ lại đóng khoản 2% tương ứng; khoản này tách khỏi giá bán, hồ sơ quản lý/phân bổ phù hợp khi đánh giá thực tế. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC154_01_UNKNOWN','TC_PV_GYC154_01','UNKNOWN', E'{"criterion_target_only": true, "enabled": true, "gate": {"any_unresolved_fact": true}, "human_approval_required_for_final": true, "numeric_rule": {"scope": "NEW_PROJECT", "start": "COMPLETION_AND_ACCEPTANCE_INTO_USE", "warranty_min_months": 60}, "predicate": "UNKNOWN n\\u1ebfu ngu\\u1ed3n/phi\\u00ean b\\u1ea3n/scope ho\\u1eb7c d\\u1eef ki\\u1ec7n c\\u1ea7n cho ch\\u00ednh ti\\u00eau ch\\u00ed ch\\u01b0a \\u0111\\u01b0\\u1ee3c x\\u00e1c nh\\u1eadn, t\\u00e0i li\\u1ec7u li\\u00ean quan ch\\u01b0a \\u0111\\u1ee7, OCR kh\\u00f4ng \\u0111\\u1ecdc \\u0111\\u01b0\\u1ee3c, m\\u00e2u thu\\u1eabn ch\\u01b0a x\\u1eed l\\u00fd, tr\\u01b0\\u1eddng c\\u1ee7a m\\u1eabu ch\\u01b0a \\u0111\\u01b0\\u1ee3c \\u0111i\\u1ec1n ho\\u1eb7c thi\\u1ebfu ch\\u1ee9ng t\\u1eeb th\\u1ef1c hi\\u1ec7n. C\\u1ea7n l\\u00e0m r\\u00f5: \\u0111\\u1ed1i t\\u01b0\\u1ee3ng/ ph\\u1ea1m vi b\\u1ea3o h\\u00e0nh, th\\u1eddi h\\u1ea1n, m\\u1ed1c ho\\u00e0n th\\u00e0nh v\\u00e0 nghi\\u1ec7m thu, \\u0111\\u1ea7u m\\u1ed1i v\\u00e0 c\\u00e1ch th\\u00f4ng b\\u00e1o, b\\u1ea3o h\\u00e0nh thi\\u1ebft b\\u1ecb theo nh\\u00e0 s\\u1ea3n xu\\u1ea5t.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'UNKNOWN nếu nguồn/phiên bản/scope hoặc dữ kiện cần cho chính tiêu chí chưa được xác nhận, tài liệu liên quan chưa đủ, OCR không đọc được, mâu thuẫn chưa xử lý, trường của mẫu chưa được điền hoặc thiếu chứng từ thực hiện. Cần làm rõ: đối tượng/ phạm vi bảo hành, thời hạn, mốc hoàn thành và nghiệm thu, đầu mối và cách thông báo, bảo hành thiết bị theo nhà sản xuất.',100,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC154_01_VIOLATED','TC_PV_GYC154_01','VIOLATED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": {"scope": "NEW_PROJECT", "start": "COMPLETION_AND_ACCEPTANCE_INTO_USE", "warranty_min_months": 60}, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn VIOLATED khi b\\u1eb1ng ch\\u1ee9ng ch\\u1ee9ng minh tr\\u00e1i m\\u1ec7nh \\u0111\\u1ec1: Nh\\u00e0 chung c\\u01b0 ph\\u1ea3i \\u0111\\u01b0\\u1ee3c b\\u1ea3o h\\u00e0nh t\\u1ed1i thi\\u1ec3u 60 th\\u00e1ng k\\u1ec3 t\\u1eeb khi ho\\u00e0n th\\u00e0nh x\\u00e2y d\\u1ef1ng v\\u00e0 nghi\\u1ec7m thu \\u0111\\u01b0a v\\u00e0o s\\u1eed d\\u1ee5ng. \\u0110i\\u1ec1u kho\\u1ea3n gi\\u1ea3m th\\u1eddi h\\u1ea1n/m\\u1ed1c b\\u1eaft \\u0111\\u1ea7u tr\\u00e1i lu\\u1eadt, lo\\u1ea1i tr\\u1eeb tr\\u00e1ch nhi\\u1ec7m b\\u1eaft bu\\u1ed9c ho\\u1eb7c ch\\u1ee9ng c\\u1ee9 t\\u1eeb ch\\u1ed1i/ch\\u1eadm b\\u1ea3o h\\u00e0nh kh\\u00f4ng c\\u00f3 ngo\\u1ea1i l\\u1ec7 h\\u1ee3p l\\u1ec7.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng. Điều khoản giảm thời hạn/mốc bắt đầu trái luật, loại trừ trách nhiệm bắt buộc hoặc chứng cứ từ chối/chậm bảo hành không có ngoại lệ hợp lệ.',80,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
