trống dự thảo chưa giao kết được xử lý UNKNOWN/cần hoàn thiện.',70,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_GYC154_01_SATISFIED','TC_PV_GYC154_01','SATISFIED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": {"scope": "NEW_PROJECT", "start": "COMPLETION_AND_ACCEPTANCE_INTO_USE", "warranty_min_months": 60}, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn SATISFIED cho m\\u1ec7nh \\u0111\\u1ec1: Nh\\u00e0 chung c\\u01b0 ph\\u1ea3i \\u0111\\u01b0\\u1ee3c b\\u1ea3o h\\u00e0nh t\\u1ed1i thi\\u1ec3u 60 th\\u00e1ng k\\u1ec3 t\\u1eeb khi ho\\u00e0n th\\u00e0nh x\\u00e2y d\\u1ef1ng v\\u00e0 nghi\\u1ec7m thu \\u0111\\u01b0a v\\u00e0o s\\u1eed d\\u1ee5ng. C\\u0103n h\\u1ed9 \\u0111\\u1ea7u t\\u01b0 x\\u00e2y m\\u1edbi trong scope \\u0110i\\u1ec1u 129 c\\u00f3 b\\u1ea3o h\\u00e0nh nh\\u00e0 chung c\\u01b0 \\u00edt nh\\u1ea5t 60 th\\u00e1ng t\\u1eeb ho\\u00e0n th\\u00e0nh x\\u00e2y d\\u1ef1ng v\\u00e0 nghi\\u1ec7m thu \\u0111\\u01b0a v\\u00e0o s\\u1eed d\\u1ee5ng; thi\\u1ebft b\\u1ecb \\u00e1p th\\u1eddi h\\u1ea1n nh\\u00e0 s\\u1ea3n xu\\u1ea5t, vi\\u1ec7c s\\u1eeda ch\\u1eefa c\\u00f3 ch\\u1ee9ng t\\u1eeb khi \\u0111\\u00e1nh gi\\u00e1 th\\u1ef1c hi\\u1ec7n. Kh\\u00f4ng y\\u00eau c\\u1ea7u to\\u00e0n b\\u1ed9 y\\u1ebfu t\\u1ed1 c\\u1ee7a nh\\u00f3m n\\u1ebfu ch\\u00fang n\\u1eb1m ngo\\u00e0i m\\u1ec7nh \\u0111\\u1ec1 n\\u00e0y.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận SATISFIED cho mệnh đề: Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng. Căn hộ đầu tư xây mới trong scope Điều 129 có bảo hành nhà chung cư ít nhất 60 tháng từ hoàn thành xây dựng và nghiệm thu đưa vào sử dụng; thiết bị áp thời hạn nhà sản xuất, việc sửa chữa có chứng từ khi đánh giá thực hiện. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
