INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_APT_CERTIFICATE_50D_2024_01_VIOLATED','TC_PV_APT_CERTIFICATE_50D_2024_01','VIOLATED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": {"application_submission_max_days": 50, "exception": "BUYER_VOLUNTARILY_SELF_FILES", "not_certificate_issuance_deadline": true, "start": "HANDOVER"}, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn VIOLATED khi b\\u1eb1ng ch\\u1ee9ng ch\\u1ee9ng minh tr\\u00e1i m\\u1ec7nh \\u0111\\u1ec1: Ch\\u1ee7 \\u0111\\u1ea7u t\\u01b0 n\\u1ed9p h\\u1ed3 s\\u01a1 \\u0111\\u1ec1 ngh\\u1ecb c\\u1ea5p Gi\\u1ea5y ch\\u1ee9ng nh\\u1eadn trong 50 ng\\u00e0y k\\u1ec3 t\\u1eeb b\\u00e0n giao, tr\\u1eeb khi ng\\u01b0\\u1eddi mua t\\u1ef1 nguy\\u1ec7n t\\u1ef1 l\\u00e0m th\\u1ee7 t\\u1ee5c. C\\u00f3 ng\\u00e0y g\\u1ed1c v\\u00e0 ch\\u1ee9ng t\\u1eeb x\\u00e1c \\u0111\\u1ecbnh qu\\u00e1 h\\u1ea1n n\\u1ed9p m\\u00e0 kh\\u00f4ng c\\u00f3 ngo\\u1ea1i l\\u1ec7, ho\\u1eb7c h\\u1ee3p \\u0111\\u1ed3ng lo\\u1ea1i b\\u1ecf tr\\u00e1ch nhi\\u1ec7m b\\u1eaft bu\\u1ed9c. Kh\\u00f4ng coi ch\\u01b0a \\u0111\\u01b0\\u1ee3c c\\u1ea5p gi\\u1ea5y l\\u00e0 t\\u1ef1 ch\\u1ee9ng minh n\\u1ed9p ch\\u1eadm.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận VIOLATED khi bằng chứng chứng minh trái mệnh đề: Chủ đầu tư nộp hồ sơ đề nghị cấp Giấy chứng nhận trong 50 ngày kể từ bàn giao, trừ khi người mua tự nguyện tự làm thủ tục. Có ngày gốc và chứng từ xác định quá hạn nộp mà không có ngoại lệ, hoặc hợp đồng loại bỏ trách nhiệm bắt buộc. Không coi chưa được cấp giấy là tự chứng minh nộp chậm.',80,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_APT_CERTIFICATE_50D_2024_01_MISSING','TC_PV_APT_CERTIFICATE_50D_2024_01','MISSING', E'{"criterion_target_only": true, "enabled": false, "gate": {"absence_verified": true, "coverage_complete": true, "criterion_content_absent": true, "evidence_validated": true, "exceptions_resolved": true, "mandatory_contract_content": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "template_field_unfilled": false, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": {"application_submission_max_days": 50, "exception": "BUYER_VOLUNTARILY_SELF_FILES", "not_certificate_issuance_deadline": true, "start": "HANDOVER"}, "predicate": "Kh\\u00f4ng k\\u00edch ho\\u1ea1t MISSING: ti\\u00eau ch\\u00ed ki\\u1ec3m tra n\\u1ed9i dung t\\u00f9y ch\\u1ecdn, \\u0111i\\u1ec1u kho\\u1ea3n c\\u1ea5m, ng\\u01b0\\u1ee1ng ho\\u1eb7c vi\\u1ec7c th\\u1ef1c hi\\u1ec7n; thi\\u1ebfu ch\\u1ee9ng t\\u1eeb/d\\u1eef ki\\u1ec7n l\\u00e0 UNKNOWN. Kh\\u00f4ng b\\u1eaft bu\\u1ed9c th\\u00eam m\\u1ed9t c\\u00e2u kh\\u1eb3ng \\u0111\\u1ecbnh tu\\u00e2n th\\u1ee7.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Không kích hoạt MISSING: tiêu chí kiểm tra nội dung tùy chọn, điều khoản cấm, ngưỡng hoặc việc thực hiện; thiếu chứng từ/dữ kiện là UNKNOWN. Không bắt buộc thêm một câu khẳng định tuân thủ.',70,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
INSERT INTO "knowledge"."quy_tac_quyet_dinh" ("quy_tac_id","tieu_chi_id","finding","dieu_kien_json","ly_do_chuan","uu_tien","trang_thai","human_verified","rule_version") VALUES ('QD_TC_PV_APT_CERTIFICATE_50D_2024_01_SATISFIED','TC_PV_APT_CERTIFICATE_50D_2024_01','SATISFIED', E'{"criterion_target_only": true, "enabled": true, "gate": {"evidence_validated": true, "exceptions_resolved": true, "no_unresolved_conflict": true, "scope_confirmed": true, "source_available": true, "version_resolved": true}, "human_approval_required_for_final": true, "numeric_rule": {"application_submission_max_days": 50, "exception": "BUYER_VOLUNTARILY_SELF_FILES", "not_certificate_issuance_deadline": true, "start": "HANDOVER"}, "predicate": "Ch\\u1ec9 k\\u1ebft lu\\u1eadn SATISFIED cho m\\u1ec7nh \\u0111\\u1ec1: Ch\\u1ee7 \\u0111\\u1ea7u t\\u01b0 n\\u1ed9p h\\u1ed3 s\\u01a1 \\u0111\\u1ec1 ngh\\u1ecb c\\u1ea5p Gi\\u1ea5y ch\\u1ee9ng nh\\u1eadn trong 50 ng\\u00e0y k\\u1ec3 t\\u1eeb b\\u00e0n giao, tr\\u1eeb khi ng\\u01b0\\u1eddi mua t\\u1ef1 nguy\\u1ec7n t\\u1ef1 l\\u00e0m th\\u1ee7 t\\u1ee5c. Trong scope kho\\u1ea3n 3 \\u0110i\\u1ec1u 17, ch\\u1ee7 \\u0111\\u1ea7u t\\u01b0 n\\u1ed9p h\\u1ed3 s\\u01a1 trong 50 ng\\u00e0y t\\u1eeb b\\u00e0n giao, tr\\u1eeb ng\\u01b0\\u1eddi mua t\\u1ef1 nguy\\u1ec7n t\\u1ef1 l\\u00e0m; ph\\u1ea3i ph\\u00e2n bi\\u1ec7t n\\u1ed9p h\\u1ed3 s\\u01a1 v\\u1edbi vi\\u1ec7c c\\u01a1 quan c\\u1ea5p gi\\u1ea5y. Kh\\u00f4ng y\\u00eau c\\u1ea7u to\\u00e0n b\\u1ed9 y\\u1ebfu t\\u1ed1 c\\u1ee7a nh\\u00f3m n\\u1ebfu ch\\u00fang n\\u1eb1m ngo\\u00e0i m\\u1ec7nh \\u0111\\u1ec1 n\\u00e0y.", "scope_of_facts": "CURRENT_CRITERION", "template_output": "DRAFT"}'::jsonb,'Chỉ kết luận SATISFIED cho mệnh đề: Chủ đầu tư nộp hồ sơ đề nghị cấp Giấy chứng nhận trong 50 ngày kể từ bàn giao, trừ khi người mua tự nguyện tự làm thủ tục. Trong scope khoản 3 Điều 17, chủ đầu tư nộp hồ sơ trong 50 ngày từ bàn giao, trừ người mua tự nguyện tự làm; phải phân biệt nộp hồ sơ với việc cơ quan cấp giấy. Không yêu cầu toàn bộ yếu tố của nhóm nếu chúng nằm ngoài mệnh đề này.',60,'AI_LEGAL_ANNOTATED_PENDING_HUMAN',false,'CAN_HO_SEED_RULES_20261007');
