INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC005_01_MISSING','COMPLIANCE','MISSING','Điền tên theo hồ sơ định danh/đăng ký và bổ sung người đại diện, căn cứ ủy quyền khi áp dụng. Mục tiêu chỉ là tiêu chí TC_PV_GYC005_01: Tên bên bán và bên mua xác định được. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Bên bán: [tên theo hồ sơ], do [người có thẩm quyền] đại diện [nếu áp dụng]. Bên mua: [tên theo hồ sơ], do [người có thẩm quyền] đại diện [nếu áp dụng].','Kiểm tra lại TC_PV_GYC005_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu tên, mã định danh phù hợp và chữ ký/ủy quyền; không xác nhận giao dịch đã ký chỉ từ tên.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC005_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có', E'["T\\u00ean b\\u00ean b\\u00e1n v\\u00e0 b\\u00ean mua x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c.", "t\\u00ean \\u0111\\u1ea7y \\u0111\\u1ee7 b\\u00ean b\\u00e1n", "t\\u00ean \\u0111\\u1ea7y \\u0111\\u1ee7 b\\u00ean mua", "t\\u01b0 c\\u00e1ch ng\\u01b0\\u1eddi \\u0111\\u1ea1i di\\u1ec7n n\\u1ebfu c\\u00f3"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC005_01_VIOLATED','COMPLIANCE','VIOLATED','Điền tên theo hồ sơ định danh/đăng ký và bổ sung người đại diện, căn cứ ủy quyền khi áp dụng. Mục tiêu chỉ là tiêu chí TC_PV_GYC005_01: Tên bên bán và bên mua xác định được. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Bên bán: [tên theo hồ sơ], do [người có thẩm quyền] đại diện [nếu áp dụng]. Bên mua: [tên theo hồ sơ], do [người có thẩm quyền] đại diện [nếu áp dụng].','Kiểm tra lại TC_PV_GYC005_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu tên, mã định danh phù hợp và chữ ký/ủy quyền; không xác nhận giao dịch đã ký chỉ từ tên.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AMEND_OR_PERFORM_CORRECTIVE_ACTION','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC005_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có', E'["T\\u00ean b\\u00ean b\\u00e1n v\\u00e0 b\\u00ean mua x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c.", "t\\u00ean \\u0111\\u1ea7y \\u0111\\u1ee7 b\\u00ean b\\u00e1n", "t\\u00ean \\u0111\\u1ea7y \\u0111\\u1ee7 b\\u00ean mua", "t\\u01b0 c\\u00e1ch ng\\u01b0\\u1eddi \\u0111\\u1ea1i di\\u1ec7n n\\u1ebfu c\\u00f3"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC005_01_UNKNOWN','COMPLIANCE','UNKNOWN','Yêu cầu hồ sơ để làm rõ đúng tiêu chí: Tên bên bán và bên mua xác định được. Hồ sơ cần: tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có. Chưa sửa điều khoản hoặc kết luận vi phạm khi thiếu căn cứ.','Chưa đủ căn cứ đánh giá TC_PV_GYC005_01. Cần cung cấp [tài liệu còn thiếu thuộc tiêu chí] và xác nhận [mốc/ngoại lệ chưa rõ].','Kiểm tra lại TC_PV_GYC005_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu tên, mã định danh phù hợp và chữ ký/ủy quyền; không xác nhận giao dịch đã ký chỉ từ tên.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','REQUEST_VERIFICATION','REVIEW_REQUIRED','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC005_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. tên đầy đủ bên bán, tên đầy đủ bên mua, tư cách người đại diện nếu có', E'["T\\u00ean b\\u00ean b\\u00e1n v\\u00e0 b\\u00ean mua x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c.", "t\\u00ean \\u0111\\u1ea7y \\u0111\\u1ee7 b\\u00ean b\\u00e1n", "t\\u00ean \\u0111\\u1ea7y \\u0111\\u1ee7 b\\u00ean mua", "t\\u01b0 c\\u00e1ch ng\\u01b0\\u1eddi \\u0111\\u1ea1i di\\u1ec7n n\\u1ebfu c\\u00f3"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC005_02_MISSING','COMPLIANCE','MISSING','Bổ sung địa chỉ theo hồ sơ và thống nhất địa chỉ nhận thông báo trong hợp đồng/phụ lục. Mục tiêu chỉ là tiêu chí TC_PV_GYC005_02: Địa chỉ của các bên xác định được. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Địa chỉ Bên bán: [địa chỉ xác minh]. Địa chỉ Bên mua: [địa chỉ xác minh]. Địa chỉ nhận thông báo: [chỉ ghi khác nếu có thỏa thuận].','Kiểm tra lại TC_PV_GYC005_02 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Kiểm tra đủ hai bên, thống nhất với điều khoản thông báo và phụ lục.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','MEDIUM','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC005_02','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. địa chỉ bên bán, địa chỉ bên mua, địa chỉ nhận thông báo khi khác', E'["\\u0110\\u1ecba ch\\u1ec9 c\\u1ee7a c\\u00e1c b\\u00ean x\\u00e1c \\u0111\\u1ecbnh \\u0111\\u01b0\\u1ee3c.", "\\u0111\\u1ecba ch\\u1ec9 b\\u00ean b\\u00e1n", "\\u0111\\u1ecba ch\\u1ec9 b\\u00ean mua", "\\u0111\\u1ecba ch\\u1ec9 nh\\u1eadn th\\u00f4ng b\\u00e1o khi kh\\u00e1c"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
