INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC062_01_VIOLATED','COMPLIANCE','VIOLATED','Điều chỉnh lịch thu về đúng ngưỡng và tiến độ; đối soát khoản đã thu vượt và xử lý hoàn trả/bù trừ bằng thỏa thuận hợp pháp. Mục tiêu chỉ là tiêu chí TC_PV_GYC062_01: Lần thanh toán đầu tiên không quá 30% giá trị hợp đồng, bao gồm cả tiền đặt cọc. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Lần đầu, gồm đặt cọc: không quá 30% giá trị hợp đồng. Lũy kế trước bàn giao: không quá 70%, hoặc 50% khi bên bán thuộc diện khoản 4 Điều 10. Khi chưa được cấp Giấy chứng nhận: không quá 95%. Chỉ dùng trong scope Điều 25 đã xác nhận.','Kiểm tra lại TC_PV_GYC062_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Tính tỷ lệ từng mốc bằng số liệu và mẫu số thực; kiểm tra tiến độ xây dựng, ngoại lệ và luật theo thời điểm.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AMEND_OR_PERFORM_CORRECTIVE_ACTION','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC062_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. giá trị hợp đồng làm mẫu số, đặt cọc, lịch và khoản đã thu, tình trạng bàn giao/cấp giấy, tư cách vốn nước ngoài khi áp dụng', E'["L\\u1ea7n thanh to\\u00e1n \\u0111\\u1ea7u ti\\u00ean kh\\u00f4ng qu\\u00e1 30% gi\\u00e1 tr\\u1ecb h\\u1ee3p \\u0111\\u1ed3ng, bao g\\u1ed3m c\\u1ea3 ti\\u1ec1n \\u0111\\u1eb7t c\\u1ecdc.", "gi\\u00e1 tr\\u1ecb h\\u1ee3p \\u0111\\u1ed3ng l\\u00e0m m\\u1eabu s\\u1ed1", "\\u0111\\u1eb7t c\\u1ecdc", "l\\u1ecbch v\\u00e0 kho\\u1ea3n \\u0111\\u00e3 thu", "t\\u00ecnh tr\\u1ea1ng b\\u00e0n giao/c\\u1ea5p gi\\u1ea5y", "t\\u01b0 c\\u00e1ch v\\u1ed1n n\\u01b0\\u1edbc ngo\\u00e0i khi \\u00e1p d\\u1ee5ng"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
