11\\u1eb7t c\\u1ecdc", "l\\u1ecbch v\\u00e0 kho\\u1ea3n \\u0111\\u00e3 thu", "t\\u00ecnh tr\\u1ea1ng b\\u00e0n giao/c\\u1ea5p gi\\u1ea5y", "t\\u01b0 c\\u00e1ch v\\u1ed1n n\\u01b0\\u1edbc ngo\\u00e0i khi \\u00e1p d\\u1ee5ng"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
