ao/c\\u1ea5p gi\\u1ea5y", "t\\u01b0 c\\u00e1ch v\\u1ed1n n\\u01b0\\u1edbc ngo\\u00e0i khi \\u00e1p d\\u1ee5ng"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC104_01_MISSING','COMPLIANCE','MISSING','Tách khoản bảo trì, ghi rõ căn cứ tính và trách nhiệm chủ sở hữu; đối soát chứng từ nộp, bàn giao và sử dụng. Mục tiêu chỉ là tiêu chí TC_PV_GYC104_01: Người mua phải đóng kinh phí bảo trì bằng 2% giá trị căn hộ/phần diện tích bán; khoản này tính riêng với tiền bán và phải quy định rõ trong hợp đồng. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Kinh phí bảo trì phần sở hữu chung: 2% giá trị căn hộ/phần diện tích thuộc diện áp dụng, tính riêng với giá bán. Chủ thể đóng, thời điểm nộp và tài khoản thực hiện theo Điều 152–153 và hồ sơ xác minh.','Kiểm tra lại TC_PV_GYC104_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối soát giá trị căn cứ, số tiền và khoản dành phần chủ đầu tư giữ lại; không tự lấy 2% mọi khoản thu hoặc mọi tài sản.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC104_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. mức 2% khi áp dụng, giá trị căn hộ/phần diện tích làm căn cứ, tách khoản bảo trì khỏi giá bán, trách nhiệm từng chủ sở hữu, tài khoản và chứng từ', E'["Ng\\u01b0\\u1eddi mua ph\\u1ea3i \\u0111\\u00f3ng kinh ph\\u00ed b\\u1ea3o tr\\u00ec b\\u1eb1ng 2% gi\\u00e1 tr\\u1ecb c\\u0103n h\\u1ed9/ph\\u1ea7n di\\u1ec7n t\\u00edch b\\u00e1n; kho\\u1ea3n n\\u00e0y t\\u00ednh ri\\u00eang v\\u1edbi ti\\u1ec1n b\\u00e1n v\\u00e0 ph\\u1ea3i quy \\u0111\\u1ecbnh r\\u00f5 trong h\\u1ee3p \\u0111\\u1ed3ng.", "m\\u1ee9c 2% khi \\u00e1p d\\u1ee5ng", "gi\\u00e1 tr\\u1ecb c\\u0103n h\\u1ed9/ph\\u1ea7n di\\u1ec7n t\\u00edch l\\u00e0m c\\u0103n c\\u1ee9", "t\\u00e1ch kho\\u1ea3n b\\u1ea3o tr\\u00ec kh\\u1ecfi gi\\u00e1 b\\u00e1n", "tr\\u00e1ch nhi\\u1ec7m t\\u1eebng ch\\u1ee7 s\\u1edf h\\u1eefu", "t\\u00e0i kho\\u1ea3n v\\u00e0 ch\\u1ee9ng t\\u1eeb"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
