3n b\\u1ea3o tr\\u00ec kh\\u1ecfi gi\\u00e1 b\\u00e1n", "tr\\u00e1ch nhi\\u1ec7m t\\u1eebng ch\\u1ee7 s\\u1edf h\\u1eefu", "t\\u00e0i kho\\u1ea3n v\\u00e0 ch\\u1ee9ng t\\u1eeb"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_GYC154_01_MISSING','COMPLIANCE','MISSING','Sửa thời hạn, mốc tính và phạm vi; xác định đầu mối tiếp nhận, hồ sơ nghiệm thu và cơ chế sửa chữa. Mục tiêu chỉ là tiêu chí TC_PV_GYC154_01: Nhà chung cư phải được bảo hành tối thiểu 60 tháng kể từ khi hoàn thành xây dựng và nghiệm thu đưa vào sử dụng. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Nhà chung cư được bảo hành tối thiểu 60 tháng kể từ hoàn thành xây dựng và nghiệm thu đưa vào sử dụng, trong scope Điều 129. Thiết bị áp thời hạn nhà sản xuất. Đầu mối tiếp nhận: [thông tin xác minh].','Kiểm tra lại TC_PV_GYC154_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Đối chiếu ngày nghiệm thu, phạm vi nhà/thiết bị và hồ sơ yêu cầu, sửa chữa; không tự bắt đầu lại 60 tháng từ bán lại/bàn giao.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','ADD','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_GYC154_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. đối tượng/ phạm vi bảo hành, thời hạn, mốc hoàn thành và nghiệm thu, đầu mối và cách thông báo, bảo hành thiết bị theo nhà sản xuất', E'["Nh\\u00e0 chung c\\u01b0 ph\\u1ea3i \\u0111\\u01b0\\u1ee3c b\\u1ea3o h\\u00e0nh t\\u1ed1i thi\\u1ec3u 60 th\\u00e1ng k\\u1ec3 t\\u1eeb khi ho\\u00e0n th\\u00e0nh x\\u00e2y d\\u1ef1ng v\\u00e0 nghi\\u1ec7m thu \\u0111\\u01b0a v\\u00e0o s\\u1eed d\\u1ee5ng.", "\\u0111\\u1ed1i t\\u01b0\\u1ee3ng/ ph\\u1ea1m vi b\\u1ea3o h\\u00e0nh", "th\\u1eddi h\\u1ea1n", "m\\u1ed1c ho\\u00e0n th\\u00e0nh v\\u00e0 nghi\\u1ec7m thu", "\\u0111\\u1ea7u m\\u1ed1i v\\u00e0 c\\u00e1ch th\\u00f4ng b\\u00e1o", "b\\u1ea3o h\\u00e0nh thi\\u1ebft b\\u1ecb theo nh\\u00e0 s\\u1ea3n xu\\u1ea5t"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
