INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_APT_CERTIFICATE_50D_2024_01_VIOLATED','COMPLIANCE','VIOLATED','Yêu cầu biên nhận nộp hồ sơ, xác định ngày gốc và trách nhiệm hỗ trợ; xử lý chậm nộp theo hồ sơ thực tế. Mục tiêu chỉ là tiêu chí TC_PV_APT_CERTIFICATE_50D_2024_01: Chủ đầu tư nộp hồ sơ đề nghị cấp Giấy chứng nhận trong 50 ngày kể từ bàn giao, trừ khi người mua tự nguyện tự làm thủ tục. Hợp đồng đã ký cần sửa đổi theo phương thức hợp pháp và lưu chứng cứ.','Chủ đầu tư thực hiện nộp hồ sơ đề nghị cấp Giấy chứng nhận trong 50 ngày kể từ bàn giao, khi khoản 3 Điều 17 áp dụng; trường hợp người mua tự nguyện tự làm được lập bằng chứng riêng.','Kiểm tra lại TC_PV_APT_CERTIFICATE_50D_2024_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Kiểm tra ngày bàn giao, biên nhận cơ quan và ngoại lệ; không hứa cơ quan cấp giấy trong 50 ngày.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','AMEND_OR_PERFORM_CORRECTIVE_ACTION','HIGH','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_APT_CERTIFICATE_50D_2024_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. chủ thể thực hiện thủ tục, ngày bàn giao hoặc sự kiện gốc, thời điểm nộp hồ sơ, nguyện vọng tự làm của người mua nếu có, biên nhận hồ sơ', E'["Ch\\u1ee7 \\u0111\\u1ea7u t\\u01b0 n\\u1ed9p h\\u1ed3 s\\u01a1 \\u0111\\u1ec1 ngh\\u1ecb c\\u1ea5p Gi\\u1ea5y ch\\u1ee9ng nh\\u1eadn trong 50 ng\\u00e0y k\\u1ec3 t\\u1eeb b\\u00e0n giao, tr\\u1eeb khi ng\\u01b0\\u1eddi mua t\\u1ef1 nguy\\u1ec7n t\\u1ef1 l\\u00e0m th\\u1ee7 t\\u1ee5c.", "ch\\u1ee7 th\\u1ec3 th\\u1ef1c hi\\u1ec7n th\\u1ee7 t\\u1ee5c", "ng\\u00e0y b\\u00e0n giao ho\\u1eb7c s\\u1ef1 ki\\u1ec7n g\\u1ed1c", "th\\u1eddi \\u0111i\\u1ec3m n\\u1ed9p h\\u1ed3 s\\u01a1", "nguy\\u1ec7n v\\u1ecdng t\\u1ef1 l\\u00e0m c\\u1ee7a ng\\u01b0\\u1eddi mua n\\u1ebfu c\\u00f3", "bi\\u00ean nh\\u1eadn h\\u1ed3 s\\u01a1"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_TC_PV_APT_CERTIFICATE_50D_2024_01_UNKNOWN','COMPLIANCE','UNKNOWN','Yêu cầu hồ sơ để làm rõ đúng tiêu chí: Chủ đầu tư nộp hồ sơ đề nghị cấp Giấy chứng nhận trong 50 ngày kể từ bàn giao, trừ khi người mua tự nguyện tự làm thủ tục. Hồ sơ cần: chủ thể thực hiện thủ tục, ngày bàn giao hoặc sự kiện gốc, thời điểm nộp hồ sơ, nguyện vọng tự làm của người mua nếu có, biên nhận hồ sơ. Chưa sửa điều khoản hoặc kết luận vi phạm khi thiếu căn cứ.','Chưa đủ căn cứ đánh giá TC_PV_APT_CERTIFICATE_50D_2024_01. Cần cung cấp [tài liệu còn thiếu thuộc tiêu chí] và xác nhận [mốc/ngoại lệ chưa rõ].','Kiểm tra lại TC_PV_APT_CERTIFICATE_50D_2024_01 với đúng nguồn/phiên bản và bằng chứng đã bổ sung. Kiểm tra ngày bàn giao, biên nhận cơ quan và ngoại lệ; không hứa cơ quan cấp giấy trong 50 ngày.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','REQUEST_VERIFICATION','REVIEW_REQUIRED','AI_LEGAL_ANNOTATED_PENDING_HUMAN','SOURCE_LINKED_AI_ANNOTATED','TC_PV_APT_CERTIFICATE_50D_2024_01','Các đoạn/phụ lục sửa đổi hợp lệ hoặc chứng từ liên quan đúng tiêu chí. chủ thể thực hiện thủ tục, ngày bàn giao hoặc sự kiện gốc, thời điểm nộp hồ sơ, nguyện vọng tự làm của người mua nếu có, biên nhận hồ sơ', E'["Ch\\u1ee7 \\u0111\\u1ea7u t\\u01b0 n\\u1ed9p h\\u1ed3 s\\u01a1 \\u0111\\u1ec1 ngh\\u1ecb c\\u1ea5p Gi\\u1ea5y ch\\u1ee9ng nh\\u1eadn trong 50 ng\\u00e0y k\\u1ec3 t\\u1eeb b\\u00e0n giao, tr\\u1eeb khi ng\\u01b0\\u1eddi mua t\\u1ef1 nguy\\u1ec7n t\\u1ef1 l\\u00e0m th\\u1ee7 t\\u1ee5c.", "ch\\u1ee7 th\\u1ec3 th\\u1ef1c hi\\u1ec7n th\\u1ee7 t\\u1ee5c", "ng\\u00e0y b\\u00e0n giao ho\\u1eb7c s\\u1ef1 ki\\u1ec7n g\\u1ed1c", "th\\u1eddi \\u0111i\\u1ec3m n\\u1ed9p h\\u1ed3 s\\u01a1", "nguy\\u1ec7n v\\u1ecdng t\\u1ef1 l\\u00e0m c\\u1ee7a ng\\u01b0\\u1eddi mua n\\u1ebfu c\\u00f3", "bi\\u00ean nh\\u1eadn h\\u1ed3 s\\u01a1"]'::jsonb,'{"criterion_target_only": true, "legal_basis_must_resolve": true, "no_auto_invalidity_or_fine": true, "no_invented_names_dates_accounts": true, "not_applicable_no_remedy": true, "quote_must_match_source": true, "recommendation_null_if_satisfied": true, "related_elements_are_context_not_all_mandatory": true, "scope_required": true, "severity_from_db": true, "template_values_are_placeholders": true, "unknown_is_verification_not_violation": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_CITATION_STALE','CITATION','STALE','Đối chiếu mốc đang đánh giá và quy định chuyển tiếp trước khi sửa viện dẫn. Nếu căn cứ đúng ở ngày giao kết thì giữ căn cứ lịch sử; chỉ đề xuất thay căn cứ không còn phù hợp vấn đề đang xét.','[DỰ THẢO] Căn cứ [nguyên văn] không còn phù hợp tại [mốc đã xác nhận]. Đề nghị xác minh [quy định chuyển tiếp] và điều chỉnh căn cứ cho đúng vấn đề của giao dịch; không thay tự động bằng văn bản hiện hành.','Đối chiếu viện dẫn sau sửa với văn bản chính thức, đúng số hiệu/tên, ngày hiệu lực và chuyển tiếp tại mốc đã xác nhận; chạy lại Citation Validator. Không đổi kết quả Compliance nếu không đánh giá nhánh Applicable Law độc lập.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','CORRECT_REFERENCE','LOW','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'Viện dẫn và đoạn hợp đồng gốc; URL và bản nguồn chính thức; kết quả đối chiếu định danh/hiệu lực/mốc; căn cứ giữ hoặc sửa; đoạn sửa đổi và sự chấp thuận khi hợp đồng đã giao kết.', E'["Vi\\u1ec7n d\\u1eabn nguy\\u00ean v\\u0103n v\\u00e0 v\\u1ecb tr\\u00ed", "M\\u00e3 l\\u00fd do v\\u00e0 b\\u1eb1ng ch\\u1ee9ng ngu\\u1ed3n", "M\\u1ed1c v\\u00e0 ph\\u1ea1m vi \\u0111ang \\u0111\\u00e1nh gi\\u00e1", "C\\u0103n c\\u1ee9 chuy\\u1ec3n ti\\u1ebfp/ngo\\u1ea1i l\\u1ec7 n\\u1ebfu c\\u00f3", "H\\u00e0nh \\u0111\\u1ed9ng ph\\u00f9 h\\u1ee3p tr\\u1ea1ng th\\u00e1i; thi\\u1ebfu g\\u00ec y\\u00eau c\\u1ea7u \\u0111\\u00fang th\\u1ee9 \\u0111\\u00f3"]'::jsonb,'{"citation_does_not_drive_retrieval": true, "current_status_separate_from_historical": true, "human_review_required": true, "legal_basis_must_be_resolved": true, "no_auto_invalidity_or_fine": true, "no_auto_replace_old_law": true, "no_automatic_invalidity": true, "no_invented_replacement": true, "no_similarity_only_identity": true, "official_identity_and_temporal_evidence_required": true, "unknown_is_not_invalid": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_CITATION_INVALID','CITATION','INVALID','Xác minh thành phần sai của số hiệu, loại văn bản, tên hoặc căn cứ được sử dụng; chỉ sửa theo nguồn chính thức xác định duy nhất. Không kết luận không tồn tại chỉ vì DB chưa có.','[DỰ THẢO] Đề nghị kiểm tra thành phần [sai lệch đã xác định] của viện dẫn [nguyên văn] với [nguồn chính thức], sau đó sửa đúng căn cứ; không lựa chọn văn bản chỉ vì tên tương tự.','Đối chiếu viện dẫn sau sửa với văn bản chính thức, đúng số hiệu/tên, ngày hiệu lực và chuyển tiếp tại mốc đã xác nhận; chạy lại Citation Validator. Không đổi kết quả Compliance nếu không đánh giá nhánh Applicable Law độc lập.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','CORRECT_REFERENCE','LOW','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'Viện dẫn và đoạn hợp đồng gốc; URL và bản nguồn chính thức; kết quả đối chiếu định danh/hiệu lực/mốc; căn cứ giữ hoặc sửa; đoạn sửa đổi và sự chấp thuận khi hợp đồng đã giao kết.', E'["Vi\\u1ec7n d\\u1eabn nguy\\u00ean v\\u0103n v\\u00e0 v\\u1ecb tr\\u00ed", "M\\u00e3 l\\u00fd do v\\u00e0 b\\u1eb1ng ch\\u1ee9ng ngu\\u1ed3n", "M\\u1ed1c v\\u00e0 ph\\u1ea1m vi \\u0111ang \\u0111\\u00e1nh gi\\u00e1", "C\\u0103n c\\u1ee9 chuy\\u1ec3n ti\\u1ebfp/ngo\\u1ea1i l\\u1ec7 n\\u1ebfu c\\u00f3", "H\\u00e0nh \\u0111\\u1ed9ng ph\\u00f9 h\\u1ee3p tr\\u1ea1ng th\\u00e1i; thi\\u1ebfu g\\u00ec y\\u00eau c\\u1ea7u \\u0111\\u00fang th\\u1ee9 \\u0111\\u00f3"]'::jsonb,'{"citation_does_not_drive_retrieval": true, "current_status_separate_from_historical": true, "human_review_required": true, "legal_basis_must_be_resolved": true, "no_auto_invalidity_or_fine": true, "no_auto_replace_old_law": true, "no_automatic_invalidity": true, "no_invented_replacement": true, "no_similarity_only_identity": true, "official_identity_and_temporal_evidence_required": true, "unknown_is_not_invalid": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_CITATION_UNKNOWN','CITATION','UNKNOWN','Yêu cầu bổ sung thông tin còn thiếu: bản nguồn, số hiệu/tên đầy đủ, vị trí trích dẫn, mốc đánh giá hoặc ngữ cảnh. Giữ UNKNOWN cho đến khi xác minh; không khẳng định viện dẫn sai.','[DỰ THẢO] Chưa đủ dữ liệu xác minh [nguyên văn]. Đề nghị cung cấp [thông tin/bằng chứng cụ thể còn thiếu] để đối chiếu.','Đối chiếu viện dẫn sau sửa với văn bản chính thức, đúng số hiệu/tên, ngày hiệu lực và chuyển tiếp tại mốc đã xác nhận; chạy lại Citation Validator. Không đổi kết quả Compliance nếu không đánh giá nhánh Applicable Law độc lập.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','VERIFY_REFERENCE','REVIEW_REQUIRED','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'Viện dẫn và đoạn hợp đồng gốc; URL và bản nguồn chính thức; kết quả đối chiếu định danh/hiệu lực/mốc; căn cứ giữ hoặc sửa; đoạn sửa đổi và sự chấp thuận khi hợp đồng đã giao kết.', E'["Vi\\u1ec7n d\\u1eabn nguy\\u00ean v\\u0103n v\\u00e0 v\\u1ecb tr\\u00ed", "M\\u00e3 l\\u00fd do v\\u00e0 b\\u1eb1ng ch\\u1ee9ng ngu\\u1ed3n", "M\\u1ed1c v\\u00e0 ph\\u1ea1m vi \\u0111ang \\u0111\\u00e1nh gi\\u00e1", "C\\u0103n c\\u1ee9 chuy\\u1ec3n ti\\u1ebfp/ngo\\u1ea1i l\\u1ec7 n\\u1ebfu c\\u00f3", "H\\u00e0nh \\u0111\\u1ed9ng ph\\u00f9 h\\u1ee3p tr\\u1ea1ng th\\u00e1i; thi\\u1ebfu g\\u00ec y\\u00eau c\\u1ea7u \\u0111\\u00fang th\\u1ee9 \\u0111\\u00f3"]'::jsonb,'{"citation_does_not_drive_retrieval": true, "current_status_separate_from_historical": true, "human_review_required": true, "legal_basis_must_be_resolved": true, "no_auto_invalidity_or_fine": true, "no_auto_replace_old_law": true, "no_automatic_invalidity": true, "no_invented_replacement": true, "no_similarity_only_identity": true, "official_identity_and_temporal_evidence_required": true, "unknown_is_not_invalid": true}'::jsonb);
INSERT INTO "knowledge"."danh_muc_khuyen_nghi" ("khuyen_nghi_id","nhanh","gap_type","noi_dung","mau_sua_goi_y","kiem_tra_sau_khac_phuc","trang_thai_ra_soat","loai_hanh_dong","uu_tien","loai_du_lieu","trang_thai_nguon","tieu_chi_id","bang_chung_khac_phuc_can_luu","required_elements_json","gioi_han_sinh_json") VALUES ('KN_CITATION_DOMAIN_MISMATCH','CITATION','DOMAIN_MISMATCH','Rà soát Điều/Khoản đang được viện dẫn cho đúng loại giao dịch, chủ thể, tài sản và vấn đề pháp lý. Nêu rõ điều kiện hoặc ngoại lệ bị bỏ qua; lựa chọn căn cứ thay thế phải do nhánh Applicable Law xác định độc lập.','[DỰ THẢO] Căn cứ [nguyên văn] đang được dùng cho [vấn đề pháp lý] chưa phù hợp [phạm vi/ngoại lệ có nguồn]. Đề nghị rà soát và diễn đạt lại căn cứ đúng phạm vi, không suy ra toàn hợp đồng vô hiệu.','Đối chiếu viện dẫn sau sửa với văn bản chính thức, đúng số hiệu/tên, ngày hiệu lực và chuyển tiếp tại mốc đã xác nhận; chạy lại Citation Validator. Không đổi kết quả Compliance nếu không đánh giá nhánh Applicable Law độc lập.','AI_LEGAL_ANNOTATED_PENDING_HUMAN','CORRECT_REFERENCE','LOW','ENGINE_POLICY','CASE_OFFICIAL_SOURCE_VERIFICATION_REQUIRED',NULL,'Viện dẫn và đoạn hợp đồng gốc; URL và bản nguồn chính thức; kết quả đối chiếu định danh/hiệu lực/mốc; căn cứ giữ hoặc sửa; đoạn sửa đổi và sự chấp thuận khi hợp đồng đã giao kết.', E'["Vi\\u1ec7n d\\u1eabn nguy\\u00ean v\\u0103n v\\u00e0 v\\u1ecb tr\\u00ed", "M\\u00e3 l\\u00fd do v\\u00e0 b\\u1eb1ng ch\\u1ee9ng ngu\\u1ed3n", "M\\u1ed1c v\\u00e0 ph\\u1ea1m vi \\u0111ang \\u0111\\u00e1nh gi\\u00e1", "C\\u0103n c\\u1ee9 chuy\\u1ec3n ti\\u1ebfp/ngo\\u1ea1i l\\u1ec7 n\\u1ebfu c\\u00f3", "H\\u00e0nh \\u0111\\u1ed9ng ph\\u00f9 h\\u1ee3p tr\\u1ea1ng th\\u00e1i; thi\\u1ebfu g\\u00ec y\\u00eau c\\u1ea7u \\u0111\\u00fang th\\u1ee9 \\u0111\\u00f3"]'::jsonb,'{"citation_does_not_drive_retrieval": true, "current_status_separate_from_historical": true, "human_review_required": true, "legal_basis_must_be_resolved": true, "no_auto_invalidity_or_fine": true, "no_auto_replace_old_law": true, "no_automatic_invalidity": true, "no_invented_replacement": true, "no_similarity_only_identity": true, "official_identity_and_temporal_evidence_required": true, "unknown_is_not_invalid": true}'::jsonb);
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('DKPL0001','VBPL001','Điều 23 khoản 1',E'Điều 23. Hợp đồng giao kết với người tiêu dùng, hợp đồng theo mẫu, điều \nkiện giao dịch chung \n1. Hình thức hợp đồng giao kết với người tiêu dùng, hợp đồng theo mẫu, điều \nkiện giao dịch chung được thực hiện theo quy định của pháp luật về dân sự và quy \nđịnh khác của pháp luật có liên quan. \n2. Ngôn ngữ, hình thức của hợp đồng giao kết với người tiêu dùng, hợp đồng \ntheo mẫu, điều kiện giao dịch chung trong trường hợp bằng văn bản phải được thể \nhiện rõ ràng, dễ hiểu. \nNgôn ngữ sử dụng trong hợp đồng giao kết với người tiêu dùng, hợp đồng theo \nmẫu, điều kiện giao dịch chung là tiếng Việt. Các bên có thể thỏa thuận sử dụng \nthêm tiếng dân tộc khác của Việt Nam hoặc tiếng nước ngoài. Trong trường hợp có \nsự khác biệt giữa bản tiếng Việt với bản tiếng dân tộc khác của Việt Nam hoặc bản \ntiếng nước ngoài, bản có lợi hơn cho người tiêu dùng được ưu tiên áp dụng. \n3. Hợp đồng theo mẫu phải có các nội dung cơ bản sau đây: \na) Thông tin của các bên trong hợp đồng bao gồm: tên, địa chỉ, số điện thoại, \nphương thức liên hệ khác (nếu có); \nb) Thông tin về sản phẩm, hàng hóa, dịch vụ được bán, cung cấp theo hợp đồng; \nc) Đo lường, số lượng, khối lượng, chất lượng, công dụng, giá của sản phẩm, \nhàng hóa, dịch vụ được bán, cung cấp, các thành phần cấu thành giá cuối cùng của \nsản phẩm, hàng hóa, dịch vụ nếu pháp luật có quy định phải công khai cấu thành \ngiá của sản phẩm, hàng hóa, dịch vụ;  \nd) Phương thức, thời hạn thanh toán; \nđ) Thời gian, địa điểm, phương thức bán, cung cấp sản phẩm, hàng hóa, dịch vụ; \ne) Quyền và nghĩa vụ của các bên bảo đảm tuân thủ quy định của Luật này và \nquy định khác của pháp luật có liên quan; \n\n \n \nCÔNG BÁO/Số 865 + 866/Ngày 30-7-2023 \n55 \n \ng) Trách nhiệm bảo vệ thông tin của người tiêu dùng; \nh) Trường hợp chấm dứt thực hiện hợp đồng và trách nhiệm phát sinh do chấm \ndứt thực hiện hợp đồng; \ni) Trường hợp bất khả kháng theo quy định của pháp luật; \nk) Phương thức giải quyết tranh chấp; \nl) Thời điểm giao kết hợp đồng, thời hạn của hợp đồng. \n4. Ngoài các nội dung cơ bản quy định tại khoản 3 Điều này, hợp đồng theo \nmẫu phải tuân thủ quy định của pháp luật khác có liên quan. \n5. Chính phủ quy định chi tiết khoản 2 Điều này.','https://datafiles.chinhphu.vn/cpp/files/vbpq/2023/7/luat19_2023.pdf','AI_DOI_CHIEU_NGUON_CHINH_THUC_CHUA_DUYET','TOAN_DIEU_NGUON_CHINH_THUC',NULL,NULL,'Rà soát 2026-10-07; đoạn toàn Điều; vị trí khoản/điểm riêng tại nguon_yeu_cau. Không xác nhận toàn bộ lịch sử sửa đổi.','KE_THUA_CHUA_XAC_MINH');
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL005_17','VBPL005','Điều 17',E'Điều 17. Trách nhiệm của chủ đầu tư dự án bất động sản  \n1. Thực hiện việc đầu tư xây dựng, kinh doanh, quản lý, khai thác dự án bất \nđộng sản theo quy định của pháp luật. Thực hiện đầy đủ các nghĩa vụ của chủ đầu \ntư dự án, thực hiện lập, thẩm định, phê duyệt và triển khai thực hiện dự án theo \nquy định của pháp luật về xây dựng và pháp luật có liên quan.  \n2. Bảo đảm nguồn tài chính để thực hiện dự án theo đúng tiến độ đã được chấp \nthuận, phê duyệt. \n3. Trong thời hạn 50 ngày kể từ ngày bàn giao nhà ở cho bên mua hoặc kể từ \nthời điểm bên thuê mua nhà ở đã thanh toán đủ tiền theo thỏa thuận thì phải nộp hồ \nsơ đề nghị cơ quan nhà nước có thẩm quyền cấp giấy chứng nhận về quyền sử \ndụng đất, quyền sở hữu tài sản gắn liền với đất theo quy định của pháp luật về đất \nđai cho bên mua, thuê mua, trừ trường hợp bên mua, thuê mua tự nguyện làm thủ \ntục cấp giấy chứng nhận. \n4. Không được ủy quyền cho tổ chức, cá nhân khác ký hợp đồng đặt cọc, mua \nbán, chuyển nhượng, cho thuê mua nhà ở, công trình xây dựng, phần diện tích sàn \nxây dựng trong công trình xây dựng, quyền sử dụng đất đã có hạ tầng kỹ thuật \ntrong dự án bất động sản. \n5. Thực hiện quy định của pháp luật trong hoạt động đầu tư, xây dựng, sử dụng \nđất và giao dịch bán, cho thuê mua nhà ở, công trình xây dựng, phần diện tích sàn \nxây dựng trong công trình xây dựng bảo đảm người mua, thuê mua nhà ở, công \ntrình xây dựng, phần diện tích sàn xây dựng trong công trình xây dựng được cơ \nquan nhà nước có thẩm quyền cấp giấy chứng nhận về quyền sử dụng đất, quyền \nsở hữu tài sản gắn liền với đất theo quy định của pháp luật về đất đai đối với nhà ở, \ncông trình xây dựng, phần diện tích sàn xây dựng trong công trình xây dựng đã \nmua, thuê mua của chủ đầu tư. \n\n \n \nCÔNG BÁO/Số 43 + 44/Ngày 08-01-2024 \n37 \n \n6. Xây dựng nhà ở, công trình xây dựng và công trình hạ tầng kỹ thuật, hạ tầng \nxã hội trong dự án theo đúng quy hoạch chi tiết, thiết kế được phê duyệt, giấy phép \nxây dựng, nội dung chấp thuận chủ trương đầu tư dự án của cơ quan nhà nước có \nthẩm quyền; tuân thủ các quy chuẩn về xây dựng. \n7. Việc bàn giao nhà ở thực hiện theo quy định của pháp luật về nhà ở. \n8. Trường hợp bàn giao nhà ở xây dựng thô không phải là nhà chung cư cho \nbên mua, thuê mua thì phải hoàn thiện toàn bộ phần mặt ngoài của nhà ở đó. \n9. Trách nhiệm khác của chủ đầu tư dự án theo quy định của pháp luật.','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','AI_NGUON_CHINH_THUC_CHUA_DUYET','TOAN_DIEU_NGUON_THAM_CHIEU_KHONG_TU_AP_DUNG','16','17',NULL,'KE_THUA_CHUA_XAC_MINH');
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL005_25','VBPL005','Điều 25',E'Điều 25. Thanh toán trong mua bán, thuê mua nhà ở, công trình xây dựng \nhình thành trong tương lai \n1. Việc thanh toán trong mua bán nhà ở, công trình xây dựng, phần diện tích \nsàn xây dựng trong công trình xây dựng hình thành trong tương lai được thực hiện \nnhiều lần, lần đầu không quá 30% giá trị hợp đồng bao gồm cả tiền đặt cọc, những \nlần tiếp theo phải phù hợp với tiến độ xây dựng nhưng tổng số không quá 70% giá \ntrị hợp đồng khi chưa bàn giao nhà ở, công trình xây dựng, phần diện tích sàn xây \ndựng trong công trình xây dựng cho bên mua; trường hợp bên bán là tổ chức kinh \ntế có vốn đầu tư nước ngoài quy định tại khoản 4 Điều 10 của Luật này thì tổng số \nkhông quá 50% giá trị hợp đồng. \n2. Việc thanh toán trong thuê mua nhà ở, công trình xây dựng, phần diện tích \nsàn xây dựng trong công trình xây dựng hình thành trong tương lai được thực hiện \nnhiều lần, lần đầu không quá 30% giá trị hợp đồng bao gồm cả tiền đặt cọc, những \nlần tiếp theo phải phù hợp với tiến độ xây dựng đến khi bàn giao nhà ở, công trình \nxây dựng, phần diện tích sàn xây dựng trong công trình xây dựng cho bên thuê \nmua nhưng tổng số tiền thanh toán trước cho bên cho thuê mua không quá 50% \n\n \n \nCÔNG BÁO/Số 43 + 44/Ngày 08-01-2024 \n49 \n \ngiá trị hợp đồng thuê mua nhà ở, công trình xây dựng, phần diện tích sàn xây dựng \ntrong công trình xây dựng. Số tiền còn lại được tính thành tiền thuê để trả cho bên \ncho thuê mua trong một thời hạn nhất định theo thỏa thuận trong hợp đồng. \n3. Nếu bên mua, thuê mua chưa được cấp giấy chứng nhận về quyền sử dụng \nđất, quyền sở hữu tài sản gắn liền với đất theo quy định của pháp luật về đất đai thì \nbên bán, cho thuê mua không được thu quá 95% giá trị hợp đồng; giá trị còn lại \ncủa hợp đồng được thanh toán khi cơ quan nhà nước có thẩm quyền đã cấp giấy \nchứng nhận về quyền sử dụng đất, quyền sở hữu tài sản gắn liền với đất theo quy \nđịnh của pháp luật về đất đai cho bên mua, thuê mua.','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat29.pdf','AI_NGUON_CHINH_THUC_CHUA_DUYET','TOAN_DIEU_NGUON_THAM_CHIEU_KHONG_TU_AP_DUNG','28','29',NULL,'KE_THUA_CHUA_XAC_MINH');
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL007_129','VBPL007','Điều 129',E'Điều 129. Bảo hành nhà ở\n    1. Tổ chức, cá nhân thi công xây dựng nhà ở phải bảo hành nhà ở theo quy\nđịnh của pháp luật về xây dựng; tổ chức, cá nhân cung ứng trang thiết bị nhà ở\nphải bảo hành trang thiết bị theo thời hạn do nhà sản xuất quy định.\n    Trường hợp đầu tư xây dựng nhà ở để bán, cho thuê mua thì bên bán, bên cho\nthuê mua nhà ở có trách nhiệm bảo hành nhà ở theo quy định tại khoản 2 và khoản 3\nĐiều này. Bên bán, bên cho thuê mua nhà ở có quyền yêu cầu tổ chức, cá nhân thi công\nxây dựng, cung ứng trang thiết bị thực hiện trách nhiệm bảo hành theo quy định\ncủa pháp luật.\n    2. Nhà ở được bảo hành kể từ khi hoàn thành việc xây dựng và nghiệm thu đưa\nvào sử dụng với thời hạn như sau:\n     a) Đối với nhà chung cư thì tối thiểu là 60 tháng;\n     b) Đối với nhà ở riêng lẻ thì tối thiểu là 24 tháng.\n    3. Nội dung bảo hành nhà ở bao gồm sửa chữa, khắc phục các hư hỏng khung,\ncột, dầm, sàn, tường, trần, mái, sân thượng, cầu thang bộ, các phần ốp, lát, trát, hệ\nthống cung cấp chất đốt, hệ thống cấp điện sinh hoạt, cấp điện chiếu sáng, bể nước\nvà hệ thống cấp nước sinh hoạt, bể phốt và hệ thống thoát nước thải, chất thải sinh\nhoạt, khắc phục các trường hợp nghiêng, lún, nứt, sụt nhà ở và các nội dung khác\ntheo thỏa thuận trong hợp đồng mua bán, thuê mua nhà ở. Đối với các trang thiết\nbị khác gắn với nhà ở thì bên bán, bên cho thuê mua nhà ở thực hiện bảo hành sửa\nchữa, thay thế theo thời hạn quy định của nhà sản xuất.\n\n                    CÔNG BÁO/Số 39 + 40/Ngày 08-01-2024                         13','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat27_tiep.pdf','OFFICIAL_TEXT_EXTRACTED_PENDING_HUMAN','ARTICLE',NULL,NULL,'Bản gốc 2023. Hiệu lực Điều 197 đã sửa bởi Luật 43/2024; tham chiếu văn bản hợp nhất khi xét sửa đổi.','OFFICIAL_SOURCE');
INSERT INTO "knowledge"."dieu_khoan_phap_ly" ("dieu_khoan_id","van_ban_id","vi_tri","noi_dung_nguon","url_nguon","trang_thai_xac_minh","loai_doan_nguon","page_start","page_end","ghi_chu_trich_xuat","loai_du_lieu") VALUES ('ART_VBPL007_152','VBPL007','Điều 152',E'Điều 152. Kinh phí bảo trì của nhà chung cư có nhiều chủ sở hữu\n    1. Đối với căn hộ, phần diện tích khác trong nhà chung cư mà chủ đầu tư dự án\nđầu tư xây dựng nhà ở bán, cho thuê mua thì người mua, thuê mua phải đóng kinh\nphí bảo trì là 2% giá trị căn hộ, phần diện tích bán, cho thuê mua này; khoản tiền\nnày được tính riêng với tiền bán, tiền thuê mua căn hộ, phần diện tích khác trong\nnhà chung cư và được quy định rõ trong hợp đồng mua bán, hợp đồng thuê mua.\n    2. Đối với căn hộ, phần diện tích khác trong nhà chung cư mà chủ đầu tư dự án\nđầu tư xây dựng nhà ở giữ lại không bán, không cho thuê mua hoặc chưa bán, chưa\ncho thuê mua tính tại thời điểm bàn giao đưa nhà chung cư vào sử dụng, trừ phần\ndiện tích thuộc sở hữu chung thì chủ đầu tư dự án đầu tư xây dựng nhà ở phải đóng\nkinh phí bảo trì là 2% giá trị căn hộ, phần diện tích giữ lại; phần giá trị này được\ntính theo giá bán căn hộ có giá cao nhất của nhà chung cư đó tại thời điểm bàn giao\nđưa nhà chung cư vào sử dụng.\n    3. Trường hợp chủ đầu tư dự án đầu tư xây dựng nhà ở ký hợp đồng mua bán,\nthuê mua căn hộ hoặc phần diện tích khác trong nhà chung cư trước ngày 01 tháng 7\nnăm 2006 mà chưa thu kinh phí bảo trì thì các chủ sở hữu nhà chung cư họp Hội\nnghị nhà chung cư để thống nhất mức đóng góp kinh phí này; mức đóng góp kinh\nphí có thể được nộp hằng tháng vào tài khoản tại tổ chức tín dụng hoặc chi nhánh\nngân hàng nước ngoài đang hoạt động tại Việt Nam do Ban quản trị nhà chung cư\nlập hoặc được đóng khi phát sinh công việc cần bảo trì.\n\n30                  CÔNG BÁO/Số 39 + 40/Ngày 08-01-2024\n\n    4. Trường hợp chủ đầu tư dự án đầu tư xây dựng nhà ở ký hợp đồng mua bán,\nthuê mua căn hộ hoặc phần diện tích khác trong nhà chung cư kể từ ngày 01 tháng 7\nnăm 2006 đến trước ngày Luật này có hiệu lực thi hành mà trong hợp đồng mua bán,\nthuê mua căn hộ, phần diện tích khác trong nhà chung cư không có thỏa thuận về kinh\nphí bảo trì thì chủ đầu tư dự án đầu tư xây dựng nhà ở phải đóng khoản tiền này;\ntrường hợp trong hợp đồng mua bán, thuê mua căn hộ, phần diện tích khác trong nhà\nchung cư mà giá mua, giá thuê mua chưa tính kinh phí bảo trì thì chủ sở hữu thực hiện\nđóng khoản kinh phí bảo trì theo quy định tại khoản 3 Điều này.','https://datafiles.chinhphu.vn/cpp/files/vbpq/2024/01/luat27_tiep.pdf','OFFICIAL_TEXT_EXTRACTED_PENDING_HUMAN','ARTICLE',NULL,NULL,'Bản gốc 2023. Hiệu lực Điều 197 đã sửa bởi Luật 43/2024; tham chiếu văn bản hợp nhất khi xét sửa đổi.','OFFICIAL_SOURCE');
